function snapshotForAgentSession(terminalId: string, cwd: string, agentType: string) {
    try {
        const { createBackup, getBackupSettings } = require('./main/backup/BackupService');
        const settings = getBackupSettings();
        if (settings.autoBackup && db) {
            createBackup(db, 'agent-session')
                .then((m: any) => console.log(`[Backup] agent-session (${terminalId}/${agentType}): ${m.backupFile}`))
                .catch((e: any) => console.error('[Backup] agent-session DB snapshot failed:', e));
        }
        if (cwd && require('fs').existsSync(cwd)) {
            const projectRow = db ? db.prepare('SELECT id, name FROM projects WHERE path = ?').get(cwd) as any : null;
            const projectId = projectRow?.id || require('path').basename(cwd) || cwd;
            const { createProjectBackup } = require('./services/ProjectBackupService.cjs');
            createProjectBackup(projectId, cwd, `Pre-agent ${agentType} session ${terminalId.slice(0, 6)}`, { trigger: 'agent-session' })
                .then((r: any) => console.log(r.success
                    ? `[ProjectBackup] agent-session: ${r.data?.label} (${r.data?.fileCount} files, ${r.data?.totalSize} bytes)`
                    : `[ProjectBackup] agent-session skipped: ${r.error}`))
                .catch((e: any) => console.error('[ProjectBackup] agent-session failed:', e));
        }
    } catch (e: any) {
        console.error('[Backup] agent-session snapshot failed:', e);
    }
}

// Get/set user preferences (category overrides, custom colors)
interface UserPreferences {
    browserTrackingPort?: number;
    browserTrackingEnabled?: boolean;
    browserExcludedDomains?: string[];
    browserWithExtension?: string;
    browserProcessNames?: string[];
    mainBrowser?: string;
    [key: string]: any;
}

// Map browser brand names to OS process names (what active-win returns)
// Key = browser brand name, values = possible process names (without .exe)
// Handles cases where the UA brand name differs from the executable name
const BROWSER_PROCESS_NAMES: Record<string, string[]> = {
    'comet': ['chrome', 'comet', 'chromium'],
    'chrome': ['chrome', 'chromium'],
    'brave': ['brave', 'chrome'],
    'edge': ['msedge', 'edge'],
    'opera': ['opera'],
    'vivaldi': ['vivaldi'],
    'firefox': ['firefox'],
    'arc': ['arc'],
    'safari': ['safari'],
    'zen': ['zen', 'zen-browser', 'zenbrowser'],
  };
function getBrowserProcessNames(browserName: string): string[] {
    const key = browserName.toLowerCase();
    return BROWSER_PROCESS_NAMES[key] || [key];
}

function isAppMatchingBrowser(appName: string, browserName: string): boolean {
    if (!appName || !browserName) return false;
    const appLower = appName.toLowerCase().replace(/\.exe$/i, '');
    const browserLower = browserName.toLowerCase();
    // Direct match (both directions) + process name alias matching
    return appLower.includes(browserLower) ||
        browserLower.includes(appLower) ||
        getBrowserProcessNames(browserName).some(p => appLower.includes(p));
}

