electron_1.ipcMain.handle('stt:native-start', (event, lang) => {
    // Native speech engine is Windows-only (System.Speech via powershell.exe).
    // On Linux/macOS the renderer falls back to API (Groq whisper) or browser
    // speech — never spawn powershell here (ENOENT + confusing error loop).
    if (process.platform !== 'win32') {
        return { ok: false, error: 'Native speech is Windows-only. On Linux use Settings → General → Voice & Speech → API key (Groq whisper, free tier) or browser speech.' };
    }
    try {
        sttKillNative();
        const scriptPath = path_1.default.join(userDataPath, 'stt-native.ps1');
        try { fs_1.default.writeFileSync(scriptPath, STT_NATIVE_SCRIPT, 'utf-8'); } catch (err) { /* ignore */ }
        sttNativeSender = event.sender;
        sttNativeChild = child_process_1.spawn('powershell.exe', ['-NoProfile', '-ExecutionPolicy', 'Bypass', '-File', scriptPath, lang || 'en-US'], { windowsHide: true });
        sttNativeChild.stdout.setEncoding('utf8');
        sttNativeChild.stdout.on('data', (chunk) => {
            const sender = sttNativeSender;
            if (!sender || sender.isDestroyed()) return;
            String(chunk).split(/\r?\n/).forEach((line) => {
                const t = line.trim();
                if (!t || t.charAt(0) !== '{') return;
                try {
                    const parsed = JSON.parse(t);
                    if (parsed && parsed.type) sender.send('stt-native-event', parsed);
                }
                catch (err) { /* not JSON — skip */ }
            });
        });
        sttNativeChild.on('error', () => {
            const sender = sttNativeSender;
            sttNativeChild = null;
            sttNativeSender = null;
            if (sender && !sender.isDestroyed()) {
                sender.send('stt-native-event', { type: 'error', text: 'Windows speech failed to start' });
            }
        });
        sttNativeChild.on('exit', (code) => {
            const sender = sttNativeSender;
            sttNativeChild = null;
            sttNativeSender = null;
            if (sender && !sender.isDestroyed() && code !== 0 && code !== null) {
                sender.send('stt-native-event', { type: 'error', text: 'Windows speech engine exited unexpectedly (code ' + code + ')' });
            }
        });
        return { ok: true };
    }
    catch (err) {
        return { ok: false, error: (err && err.message) ? err.message : 'Failed to start Windows speech' };
    }
});
electron_1.ipcMain.handle('stt:native-stop', () => {
    sttKillNative();
    return { ok: true };
});

