/**
 * Real Linux browser detection (replaces a hardcoded list that lied).
 *
 * Two independent signals, unioned:
 *  1. Installed binaries on PATH / in the usual prefixes.
 *  2. Registered `.desktop` launchers — the authoritative source on most desktops,
 *     and it catches AppImage/Flatpak installs that live outside every prefix.
 *
 * Results are cached briefly so opening Settings repeatedly does not stat the disk
 * on every render.
 */
let linuxBrowsersCache: { at: number; list: string[] } | null = null;
const LINUX_BROWSERS_TTL_MS = 60_000;

function detectLinuxBrowsers(): string[] {
    const now = Date.now();
    if (linuxBrowsersCache && now - linuxBrowsersCache.at < LINUX_BROWSERS_TTL_MS)
        return linuxBrowsersCache.list;

    const found = new Set<string>();

    // (1) Binaries on PATH + the usual install prefixes.
    const binNames: Record<string, string[]> = {
        'chrome': ['google-chrome', 'google-chrome-stable', 'chrome'],
        'chromium': ['chromium', 'chromium-browser'],
        'firefox': ['firefox', 'firefox-esr'],
        'brave': ['brave-browser', 'brave'],
        'edge': ['microsoft-edge', 'microsoft-edge-stable'],
        'opera': ['opera'],
        'vivaldi': ['vivaldi', 'vivaldi-stable'],
        'zen': ['zen', 'zen-browser'],
        'arc': ['arc'],
        'comet': ['comet'],
        'librewolf': ['librewolf'],
        'dia': ['dia'],
    };
    const pathDirs = (process.env.PATH || '').split(':').filter(Boolean);
    for (const [brand, names] of Object.entries(binNames)) {
        for (const name of names) {
            for (const dir of pathDirs) {
                try {
                    if (fs_1.default.existsSync(path_1.default.join(dir, name))) {
                        found.add(brand);
                        break;
                    }
                }
                catch { /* unreadable dir */ }
            }
            if (found.has(brand))
                break;
        }
    }

    // Common non-PATH locations (snap, flatpak, /opt, ~/.local).
    const extraRoots = [
        '/opt/google/chrome', '/opt/microsoft/msedge', '/usr/lib/brave',
        '/usr/lib/firefox', '/usr/lib/chromium', '/usr/lib/vivaldi',
        '/var/lib/flatpak/exports/bin', `${process.env.HOME || ''}/.local/bin`,
        `${process.env.HOME || ''}/.local/share/flatpak/exports/bin`,
        `${process.env.HOME || ''}/Applications`,
    ];
    const extraBins: Record<string, string[]> = {
        'chrome': ['google-chrome', 'google-chrome-stable'],
        'chromium': ['chromium'],
        'firefox': ['firefox'],
        'brave': ['brave-browser'],
        'edge': ['microsoft-edge'],
        'vivaldi': ['vivaldi'],
        'zen': ['zen'],
        'comet': ['comet'],
        'opera': ['opera'],
    };
    for (const root of extraRoots) {
        if (!root)
            continue;
        for (const [brand, names] of Object.entries(extraBins)) {
            if (found.has(brand))
                continue;
            for (const n of names) {
                try {
                    if (fs_1.default.existsSync(path_1.default.join(root, n))) {
                        found.add(brand);
                        break;
                    }
                }
                catch { /* not present */ }
            }
        }
    }

    // (2) Registered .desktop launchers — catches AppImage/Flatpak installs that
    // live outside every prefix we probed above.
    try {
        const desktopDirs = [
            '/usr/share/applications',
            '/usr/local/share/applications',
            '/var/lib/snapd/desktop/applications',
            `${process.env.HOME || ''}/.local/share/applications`,
        ];
        const desktopHints: Array<[RegExp, string]> = [
            [/google-chrome/i, 'chrome'], [/chromium/i, 'chromium'],
            [/firefox|librewolf/i, 'firefox'], [/brave/i, 'brave'],
            [/microsoft-edge|msedge/i, 'edge'], [/opera/i, 'opera'],
            [/vivaldi/i, 'vivaldi'], [/\bzen\b/i, 'zen'],
            [/arc/i, 'arc'], [/comet/i, 'comet'], [/\bdia\b/i, 'dia'],
        ];
        for (const dir of desktopDirs) {
            let entries: string[];
            try {
                entries = fs_1.default.readdirSync(dir);
            }
            catch {
                continue;
            }
            for (const file of entries) {
                if (!file.endsWith('.desktop'))
                    continue;
                for (const [re, brand] of desktopHints) {
                    if (re.test(file))
                        found.add(brand);
                }
            }
        }
    }
    catch (err) {
        console.error('[DeskFlow] .desktop scan failed:', err);
    }

    const list = [...found].sort();
    if (list.length === 0)
        console.log('[DeskFlow] detectLinuxBrowsers: nothing found via binaries or .desktop files');
    else
        console.log(`[DeskFlow] detectLinuxBrowsers: ${list.join(', ')}`);
    linuxBrowsersCache = { at: now, list };
    return list;
}

electron_1.ipcMain.handle('get-available-browsers', async () => {
    const browsers: string[] = [];
    const platform = process.platform;
    
    try {
        if (platform === 'win32') {
            const browserPaths: Record<string, string> = {
                'chrome': path_1.default.join(process.env.LOCALAPPDATA || '', 'Google', 'Chrome', 'Application', 'chrome.exe'),
                'firefox': path_1.default.join(process.env.PROGRAMFILES || 'C:\\Program Files', 'Mozilla Firefox', 'firefox.exe'),
                'edge': path_1.default.join(process.env.PROGRAMFILES || 'C:\\Program Files', 'Microsoft', 'Edge', 'Application', 'msedge.exe'),
                'brave': path_1.default.join(process.env.LOCALAPPDATA || '', 'BraveSoftware', 'Brave-Browser', 'Application', 'brave.exe'),
                'opera': path_1.default.join(process.env.APPDATA || '', 'Opera Software', 'Opera Stable', 'opera.exe'),
                'vivaldi': path_1.default.join(process.env.LOCALAPPDATA || '', 'Vivaldi', 'Application', 'vivaldi.exe'),
                'comet': path_1.default.join(process.env.LOCALAPPDATA || '', 'Programs', 'comet', 'Comet.exe'),
            };
            
            for (const [browser, browserPath] of Object.entries(browserPaths)) {
                try {
                    await fs_1.default.promises.access(browserPath);
                    browsers.push(browser);
                } catch {
                    // Browser not found at that path
                }
            }
        } else if (platform === 'darwin') {
            const macBrowserPaths: Record<string, string> = {
                'chrome': '/Applications/Google Chrome.app',
                'firefox': '/Applications/Firefox.app',
                'safari': '/Applications/Safari.app',
                'brave': '/Applications/Brave Browser.app',
                'arc': '/Applications/Arc.app',
                'edge': '/Applications/Microsoft Edge.app',
                'opera': '/Applications/Opera.app',
                'vivaldi': '/Applications/Vivaldi.app',
                'comet': '/Applications/Comet.app',
            };
            
            for (const [browser, browserPath] of Object.entries(macBrowserPaths)) {
                try {
                    await fs_1.default.promises.access(browserPath);
                    browsers.push(browser);
                } catch {
                    // Browser not found
                }
            }
        } else {
            // Linux — actually look, instead of returning a hardcoded 7-item list.
            // The old hardcoded array offered browsers that were not installed and
            // hid ones that were, which made the settings grid actively misleading.
            browsers.push(...detectLinuxBrowsers());
        }
    } catch (err) {
        console.error('[DeskFlow] Error detecting browsers:', err);
    }
    
    // Always include Chrome as fallback if none found
    if (browsers.length === 0) {
        browsers.push('chrome', 'firefox', 'edge', 'comet');
    }
    
    console.log('[DeskFlow] Detected browsers:', browsers);
    return browsers;
});

const KNOWN_BROWSERS = ['chrome', 'firefox', 'safari', 'edge', 'brave', 'opera', 'vivaldi', 'arc', 'comet', 'zen'];

electron_1.ipcMain.handle('get-tracked-browsers', async () => {
    const browsers: string[] = [];
    try {
        // Get ALL apps categorized as "Browser" from the database
        if (db) {
            const rows = db.prepare(`
                SELECT DISTINCT app FROM logs 
                WHERE LOWER(category) = 'browser'
            `).all() as { app: string }[];
            rows.forEach(row => {
                if (row.app && !browsers.includes(row.app)) {
                    browsers.push(row.app);
                }
            });
        } else if (useJson && jsonLogs.length > 0) {
            const seen = new Set<string>();
            jsonLogs.forEach(log => {
                const cat = (log.category || '').toLowerCase();
                if (cat === 'browser' && !seen.has(log.app)) {
                    seen.add(log.app);
                    browsers.push(log.app);
                }
            });
        }
        // Also check category config for apps mapped to "Browser" category
        if (categoryConfig?.appCategoryMap) {
            for (const [app, cat] of Object.entries(categoryConfig.appCategoryMap)) {
                if (cat === 'Browser' && !browsers.includes(app)) {
                    browsers.push(app);
                }
            }
        }
    } catch (err) {
        console.error('[DeskFlow] Error getting tracked browsers:', err);
    }
    // The browser with the extension should appear first in the list
    const extensionBrowser = userPreferences.browserWithExtension;
    if (extensionBrowser) {
        const idx = browsers.findIndex(b => b.toLowerCase() === extensionBrowser.toLowerCase());
        if (idx > 0) {
            browsers.splice(idx, 1);
            browsers.unshift(extensionBrowser);
        } else if (idx === -1) {
            // Add the extension browser even if not in DB yet
            browsers.unshift(extensionBrowser);
        }
    }
    console.log('[DeskFlow] Tracked browser apps:', browsers);
    return browsers;
});

