    const execPromise = (cmd: string, timeout = 3000): Promise<{ stdout: string } | null> => {
        return new Promise((resolve) => {
            const child = exec(cmd, { timeout }, (err: any, stdout: string) => {
                resolve(err ? null : { stdout: stdout.trim() });
            });
            setTimeout(() => {
                child.kill();
                resolve(null);
            }, timeout);
        });
    };

