// Get AI usage summary
electron_1.ipcMain.handle('get-ai-usage-summary', (event, period = 'week', dateOffset = 0, projectId) => {
    if (useJson) return { totalTokens: 0, totalCost: 0, byTool: {} };

    try {
        const now = new Date();
        let sinceDateStr: string | null = null;

        if (period === 'today') {
            const d = new Date(now);
            d.setDate(d.getDate() - dateOffset);
            sinceDateStr = getLocalDateStr(d);
        } else if (period === 'week') {
            sinceDateStr = getLocalDateStr(new Date(now.getTime() - (7 + dateOffset * 7) * 24 * 60 * 60 * 1000));
        } else if (period === '7day') {
            sinceDateStr = getLocalDateStr(new Date(now.getTime() - (7 + dateOffset * 7) * 24 * 60 * 60 * 1000));
        } else if (period === 'month') {
            sinceDateStr = getLocalDateStr(new Date(now.getTime() - (30 + dateOffset * 30) * 24 * 60 * 60 * 1000));
        } else if (period === '30day') {
            sinceDateStr = getLocalDateStr(new Date(now.getTime() - (30 + dateOffset * 30) * 24 * 60 * 60 * 1000));
        }

        let query = `
            SELECT
                tool,
                SUM(input_tokens) as total_input_tokens,
                SUM(output_tokens) as total_output_tokens,
                SUM(input_tokens + output_tokens + COALESCE(cache_read_tokens, 0) + COALESCE(cache_write_tokens, 0)) as total_tokens,
                SUM(cost_usd) as total_cost,
                COUNT(*) as session_count,
                SUM(message_count) as total_messages,
                MAX(date) as last_used,
                GROUP_CONCAT(DISTINCT model) as models
            FROM ai_usage
        `;
        const params: any[] = [];

        const conditions: string[] = [];
        if (sinceDateStr) conditions.push(`date >= ?`);
        if (projectId) conditions.push(`project_id = ?`);

        if (conditions.length > 0) {
            query += `WHERE ${conditions.join(' AND ')} GROUP BY tool`;
            if (sinceDateStr) params.push(sinceDateStr);
            if (projectId) params.push(projectId);
        } else {
            query += `GROUP BY tool`;
        }

        const summary = db.prepare(query).all(...params);

        const byTool: Record<string, any> = {};
        let totalTokens = 0;
        let totalCost = 0;

        for (const row of summary) {
            const models = row.models ? row.models.split(',').filter((m: string) => m) : [];
            byTool[row.tool] = {
                tokens: row.total_tokens,
                tokens_in: row.total_input_tokens || 0,
                tokens_out: row.total_output_tokens || 0,
                cost: row.total_cost,
                sessions: row.session_count,
                messageCount: row.total_messages || 0,
                lastUsed: row.last_used || null,
                models,
            };
            totalTokens += row.total_tokens;
            totalCost += row.total_cost;
        }

        return { totalTokens, totalCost, byTool, period };
    } catch {
        return { totalTokens: 0, totalCost: 0, byTool: {} };
    }
});

// Get language distribution and response time stats
electron_1.ipcMain.handle('get-ai-usage-details', (event, period = 'all', dateOffset = 0) => {
    if (useJson) return { languageDistribution: {}, avgResponseTime: 0, responseTimeByDay: {} };

    try {
        const now = new Date();
        let sinceDateStr: string | null = null;

        if (period === 'today') {
            const d = new Date(now);
            d.setDate(d.getDate() - dateOffset);
            sinceDateStr = getLocalDateStr(d);
        } else if (period === 'week') {
            sinceDateStr = getLocalDateStr(new Date(now.getTime() - (7 + dateOffset * 7) * 24 * 60 * 60 * 1000));
        } else if (period === '7day') {
            sinceDateStr = getLocalDateStr(new Date(now.getTime() - (7 + dateOffset * 7) * 24 * 60 * 60 * 1000));
        } else if (period === 'month') {
            sinceDateStr = getLocalDateStr(new Date(now.getTime() - (30 + dateOffset * 30) * 24 * 60 * 60 * 1000));
        } else if (period === '30day') {
            sinceDateStr = getLocalDateStr(new Date(now.getTime() - (30 + dateOffset * 30) * 24 * 60 * 60 * 1000));
        }

        let whereClause = '';
        const params: any[] = [];
        if (sinceDateStr) {
            whereClause = 'WHERE date >= ?';
            params.push(sinceDateStr);
        }

        // Language distribution
        const langQuery = `
            SELECT language, COUNT(*) as count, SUM(input_tokens + output_tokens) as tokens
            FROM ai_usage
            ${whereClause}
            ${sinceDateStr ? 'AND' : 'WHERE'} language IS NOT NULL AND language != ''
            GROUP BY language
            ORDER BY tokens DESC
        `;
        const langRows = db.prepare(langQuery).all(...params);
        const languageDistribution: Record<string, { count: number; tokens: number }> = {};
        for (const row of langRows) {
            languageDistribution[row.language] = { count: row.count, tokens: row.tokens };
        }

        // Average response time
        const rtQuery = `
            SELECT AVG(avg_response_time_ms) as avg_rt, date
            FROM ai_usage
            ${whereClause}
            ${sinceDateStr ? 'AND' : 'WHERE'} avg_response_time_ms > 0
            GROUP BY date
            ORDER BY date
        `;
        const rtRows = db.prepare(rtQuery).all(...params);
        let totalAvgRt = 0;
        const responseTimeByDay: Record<string, number> = {};
        for (const row of rtRows) {
            responseTimeByDay[row.date] = Math.round(row.avg_rt);
            totalAvgRt += row.avg_rt;
        }
        const avgResponseTime = rtRows.length > 0 ? Math.round(totalAvgRt / rtRows.length) : 0;

        return { languageDistribution, avgResponseTime, responseTimeByDay };
    } catch (err) {
        console.error('[DeskFlow] get-ai-usage-details error:', err);
        return { languageDistribution: {}, avgResponseTime: 0, responseTimeByDay: {} };
    }
});

// Get commit statistics
electron_1.ipcMain.handle('get-commit-stats', (event, projectId, period = 'week') => {
    if (useJson) return { totalCommits: 0, totalAdditions: 0, totalDeletions: 0 };

    try {
        let dateFilter = '';
        let projectFilter = '';

        if (projectId) {
            projectFilter = `project_id = '${projectId}'`;
        }

        const now = new Date();
        if (period === 'week') {
            const weekAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
            dateFilter = `date >= '${weekAgo.toISOString()}'`;
        } else if (period === 'month') {
            const monthAgo = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);
            dateFilter = `date >= '${monthAgo.toISOString()}'`;
        }

        const whereClause = [projectFilter, dateFilter].filter(Boolean).join(' AND ');

        const stats = db.prepare(`
            SELECT
                COUNT(*) as total_commits,
                COALESCE(SUM(additions), 0) as total_additions,
                COALESCE(SUM(deletions), 0) as total_deletions,
                COALESCE(SUM(files_changed), 0) as total_files
            FROM commits
            ${whereClause ? 'WHERE ' + whereClause : ''}
        `).get();

        return stats;
    } catch {
        return { totalCommits: 0, totalAdditions: 0, totalDeletions: 0 };
    }
});

