// ═══════════════════════════════════════════════════════════════════
// Foundation: AGENT_CONFIGS, ANSI stripping, prompt detection,
// state machine, launch verification, error diagnosis
// ═══════════════════════════════════════════════════════════════════

interface AgentConfig {
  binaryCandidates: string[];
  readyRegex: RegExp;
  installHint: string;
  bracketedPaste: boolean;
  inputMode: 'tui-ink' | 'tui-bubbletea' | 'readline';
  tuiFramework: 'ink' | 'bubbletea' | 'unknown';
  sessionIdSource: 'output' | 'db-pid';
}

const DEFAULT_AGENT = 'opencode';

const AGENT_CONFIGS: Record<string, AgentConfig> = {
    opencode: {
        binaryCandidates: ['opencode', 'opencode.cmd', 'opencode.exe'],
        // opencode is a bubbletea TUI: it never prints a ">" prompt line, so the
        // old /^(?:opencode)?\s*>\s*$/i could never match and the terminal stayed
        // 'launching' forever — prompts were queued and silently never written.
        // Readiness for this agent is decided by the bubbletea settle branch in
        // isTuiSettled(), not by this regex. Kept only as a loose fallback.
        readyRegex: /(?:^|\s)(?:opencode|›)(?:\s|$)/i,
        installHint: 'Install with: npm i -g opencode-ai (then restart the app)',
        bracketedPaste: true,
        inputMode: 'tui-bubbletea',
        tuiFramework: 'bubbletea',
        sessionIdSource: 'db-pid',
  },
  claude: {
    binaryCandidates: ['claude', 'claude.cmd', 'claude.exe'],
    readyRegex: /^(?:claude)?\s*>\s*$/i,
    installHint: 'Install with: npm i -g @anthropic-ai/claude-code (then restart the app)',
    bracketedPaste: true,
    inputMode: 'tui-ink',
    tuiFramework: 'ink',
    sessionIdSource: 'output',
  },
  gemini: {
    binaryCandidates: ['gemini', 'gemini.cmd', 'gemini.exe'],
    readyRegex: /^(?:gemini)?\s*>\s*$/i,
    installHint: 'Install with: npm i -g @google/gemini-cli (then restart the app)',
    bracketedPaste: true,
    inputMode: 'tui-ink',
    tuiFramework: 'ink',
    sessionIdSource: 'output',
  },
  codex: {
    binaryCandidates: ['codex', 'codex.cmd', 'codex.exe'],
    readyRegex: /^(?:codex)?\s*>\s*$/i,
    installHint: 'Install with: npm i -g @openai/codex (then restart the app)',
    bracketedPaste: true,
    inputMode: 'tui-ink',
    tuiFramework: 'ink',
    sessionIdSource: 'output',
  },
  hermes: {
    binaryCandidates: ['hermes', 'hermes.cmd', 'hermes.exe'],
    readyRegex: /^(?:hermes)?\s*>\s*$/i,
    installHint: 'Install the Nous Hermes CLI, ensure hermes is on PATH, then restart the app',
    bracketedPaste: false,
    inputMode: 'tui-ink',
    tuiFramework: 'unknown',
    sessionIdSource: 'output',
  },
};

const FALLBACK_READY_REGEX = /^[A-Za-z0-9_-]*\s*>\s*$/;

function getAgentConfig(agentType?: string): AgentConfig {
  return AGENT_CONFIGS[agentType ?? ''] ?? {
    binaryCandidates: agentType ? [agentType] : [],
    readyRegex: FALLBACK_READY_REGEX,
    installHint: `Could not find '${agentType}' on PATH. Install it and restart the app.`,
    bracketedPaste: false,
    inputMode: 'readline',
    tuiFramework: 'unknown',
    sessionIdSource: 'output',
  };
}

// Strip ANSI escape sequences from terminal output
function stripAnsi(s: string): string {
  if (!s) return '';
  return s
    // CSI FIRST. The catch-all \x1b[@-Z\\-_] rule below eats the ESC[ of a
    // sequence whose parameters are split across two PTY chunks, leaving the
    // tail (e.g. ";2;255;255;255m") in the buffer as literal text. That residue
    // was what detectAgentPrompt was regexing against, so the prompt never
    // matched and the agent never left 'launching'.
    .replace(/\x1b\[[0-9;:<=>?]*[ -\/]*[@-~]/g, '')
    .replace(/\x1b\][^\x07\x1b]*(?:\x07|\x1b\\)/g, '')
    .replace(/\x1b[@-Z\\-_]/g, '')
    // Residual literal tail of an SGR sequence split across two PTY chunks, e.g.
    // ";2;255;255;255m". Deliberately requires 2+ params: a single number before
    // 'm' is ordinary prose ("I am 5m tall") and must survive, and so must a bare
    // "m". Only the multi-parameter truecolor form is unambiguous ANSI debris.
    .replace(/^[;]?\d{1,3}(?:;\d{1,3})*m(?=\s|$)/gm, '')
    // SGR tail, anchored anywhere (not just line start): opencode's frame wraps,
    // so the residue can land mid-line after a CR.
    .replace(/[\s;]\d{1,3}(?:;\d{1,3})*m(?=\s|$)/g, ' ')
    // OSC/apc payload tail left when the ESC] introducer split across chunks,
    // e.g. "+q4d73" from a kitty-graphics or OSC-133 payload.
    .replace(/(?:^|[\s;])[+>][a-zA-Z0-9]{2,12}$/gm, '')
    .replace(/[\x00-\x08\x0b\x0c\x0e-\x1f]/g, '');
}

// Shell prompt patterns — these must NEVER trigger agent:ready
const SHELL_PROMPT_REGEXES: RegExp[] = [
  /^PS\s+.*>\s*$/,
  /^[A-Za-z]:\\.*>\s*$/,
  /^[^@\s]+@[^:\s]+:.*[#$]\s*$/,
];

const path = require('path');
const fs = require('fs');

function getAgentStateDir(projectCwd: string): string {
    // Prefer the PROJECT's agent/state dir (that is what AGENTS.md describes),
    // fall back to userData so packaged builds never crash.
    const candidate = projectCwd ? path.join(projectCwd, 'agent', 'state') : null;
    if (candidate && fs.existsSync(path.dirname(candidate))) {
        try { fs.mkdirSync(candidate, { recursive: true }); return candidate; } catch {}
    }
    const fallback = path.join(electron_1.app.getPath('userData'), 'agent-state');
    try { fs.mkdirSync(fallback, { recursive: true }); } catch {}
    return fallback;
}

function looksLikeShell(line: string): boolean {
  return SHELL_PROMPT_REGEXES.some((re) => re.test(line));
}

// Agent prompt detection — checks the last non-empty line of accumulated output
// against the per-agent ready regex. Strips ANSI, rejects shell prompts.
function detectAgentPrompt(buffer: string, agentType?: string): boolean {
  const clean = stripAnsi(buffer);
  const lines = clean.split(/\r?\n/);
  for (let i = lines.length - 1; i >= 0; i--) {
    const trimmed = lines[i].trim();
    if (trimmed.length === 0) continue;
    if (looksLikeShell(trimmed)) return false;
    const regex = getAgentConfig(agentType).readyRegex;
    const match = regex.test(trimmed);
    if (!match && trimmed.length > 0 && i === lines.length - 1) {
      console.log('[AGENT-READY] Last line:', JSON.stringify(trimmed.slice(0, 100)), 'regex:', regex, 'match:', match);
    }
    return match;
  }
  return false;
}

// Agent launch verification — out-of-band PATH check

interface AgentVerifyResult {
  found: boolean;
  resolvedBinary?: string;
  resolvedPath?: string;
  tried: string[];
  installHint: string;
}

function whichOne(name: string): Promise<string | null> {
  const cmd = process.platform === 'win32' ? 'where.exe' : 'which';
  return new Promise((resolve) => {
    child_process_1.execFile(cmd, [name], { timeout: 4000, windowsHide: true }, (err, stdout) => {
      if (err) return resolve(null);
      const first = stdout.split(/\r?\n/).map((l) => l.trim()).find(Boolean);
      resolve(first ?? null);
    });
  });
}

async function verifyAgent(agentType: string): Promise<AgentVerifyResult> {
  const cfg = getAgentConfig(agentType);
  const tried = cfg.binaryCandidates.length ? cfg.binaryCandidates : [agentType];
  for (const cand of tried) {
    const resolvedPath = await whichOne(cand);
    if (resolvedPath) {
      return { found: true, resolvedBinary: cand, resolvedPath, tried, installHint: cfg.installHint };
    }
  }
  return { found: false, tried, installHint: cfg.installHint };
}

// Per-terminal agent state machine
type AgentPhase = 'launching' | 'ready' | 'busy' | 'attention' | 'error';
interface AgentState {
  agentType: string;
  phase: AgentPhase;
  dataBuffer: string;
  idleSeq: number;
  launchStartedAt: number;
  lastOutputAt: number;           // Timestamp of last PTY data chunk
    verifyTimeout?: NodeJS.Timeout; // Timer for write verification
    handshakeToken?: string;
    timeoutHandle?: ReturnType<typeof setTimeout>;       // 6s force-ready backstop
    errorTimeoutHandle?: ReturnType<typeof setTimeout>;  // 15s launch-failure timer
  pendingWrites?: string[];
  currentModel?: string;
  sessionId?: string;              // captured from agent output (primary) or DB (fallback)
  sessionIdCaptured: boolean;      // true once an ID is persisted to the session row
  parsed?: ParsedAgentOutput;      // last parseAgentOutput result
  lastError?: string;              // error string when phase === 'error'
  spawnedPid?: number;             // OS PID of the spawned agent/shell process (DB correlation)
}
const agentStates = new Map<string, AgentState>();

// ---- AI Debug Vault helpers (best-effort, never throw) ----
function vaultLogSafe(ev: any) {
  try { require('./services/aiDebugVault').vaultLog(ev); } catch { }
}

function agentStatusBroadcast(id: string, st: any) {
  broadcast('agent:status', { terminalId: id, phase: st.phase, sessionId: st.sessionId, error: st.lastError });
  vaultLogSafe({ source: 'terminal-agent', event: 'state', contextId: id, payload: { phase: st.phase, sessionId: st.sessionId, error: st.lastError } });
}

function buildAgentInputPayload(data: string, agentType?: string): string {
  const normalized = String(data ?? '').replace(/\r\n?/g, '\n').trimEnd();
  const cfg = getAgentConfig(agentType);
  if (cfg.bracketedPaste) {
    return '\x1b[200~' + normalized + '\x1b[201~\r';
  }
  return normalized + '\r';
}

function getLastNonEmptyTerminalLine(buffer: string): string {
  const clean = stripAnsi(buffer);
  const lines = clean.split(/\r?\n/).map((l) => l.trim()).filter(Boolean);
  return lines[lines.length - 1] ?? '';
}

function flushPendingAgentWrites(id: string, st: AgentState) {
  if (!st.pendingWrites || st.pendingWrites.length === 0) return;
  const writes = [...st.pendingWrites];
  st.pendingWrites = [];
  for (const w of writes) {
    terminalManager.write(id, buildAgentInputPayload(w, st.agentType));
  }
}

function markAgentReady(id: string, st: AgentState) {
  if (st.phase !== 'launching') return;
  st.phase = 'ready';
  clearAgentTimeout(id);
  flushPendingAgentWrites(id, st);
  broadcast('agent:ready', { terminalId: id });
  agentStatusBroadcast(id, st);
}

function isTuiSettled(st: AgentState): boolean {
    // Must have received enough data to pass the initial boot splash
    if (st.dataBuffer.length < 150) return false;
    const lastLine = getLastNonEmptyTerminalLine(st.dataBuffer);
    if (looksLikeShell(lastLine)) return false;
    const quietFor = Date.now() - st.lastOutputAt;
    const cfg = getAgentConfig(st.agentType);
    // Ink/React TUIs (claude, codex, gemini) go fully silent on stdout while
    // waiting for stdin, so 500ms of quiet is a reliable "it's listening" signal.
    if (quietFor >= 500) return true;
    // bubbletea TUIs (opencode) redraw continuously — a cursor, a spinner, a
    // status line — so they NEVER go quiet and the old silence test could not
    // ever be true. For them, reaching the prompt region is the signal: enough
    // output has arrived, the last line is not a shell prompt, and the TUI has
    // been up for at least a second. Bounded by launchStartedAt so a stalled
    // spawn still falls through to the 15s error timeout.
    if (cfg.tuiFramework === 'bubbletea') {
        const upFor = Date.now() - (st.launchStartedAt || Date.now());
        return upFor >= 1000;
    }
    return false;
}

// Incremental output parsing + session ID capture + launch error detection.
// Called from BOTH the terminal:create and spawn-terminal data handlers after
// the dataBuffer is appended. parseAgentOutput is idempotent for session-id
// extraction (honors state.sessionIdCaptured).
function handleAgentOutputChunk(id: string, st: AgentState, data: string) {
  try {
    st.parsed = parseAgentOutput(st.dataBuffer, st.agentType, st, getAgentConfig(st.agentType).sessionIdSource);
  } catch (_e) { return; }

  // NEW: Session ID capture � primary path is agent OUTPUT, not DB path-matching.
  // Persist to terminal_sessions.resume_id immediately via the terminal?session
  // binding so the id is available even if the renderer reloads.
  if (st.parsed.sessionId && !st.sessionIdCaptured) {
    st.sessionId = st.parsed.sessionId;
    st.sessionIdCaptured = true;
    try {
      const dbSid = getSessionIdForTerminal(id);
      if (dbSid && db) {
        db.prepare('UPDATE terminal_sessions SET resume_id = ? WHERE id = ?').run(st.sessionId, dbSid);
      }
    } catch (_e) { /* silent */ }
    broadcast('agent:session-id-captured', { terminalId: id, sessionId: st.sessionId });
  }

  // NEW: Launch error state � fail fast instead of waiting for the 30s timeout.
  if (st.parsed.errors && st.parsed.errors.length > 0 && st.phase === 'launching') {
    st.phase = 'error';
    st.lastError = st.parsed.errors[0];
    clearAgentTimeout(id);
    broadcast('agent:init-error', { terminalId: id, agentType: st.agentType, reason: 'output-error', detail: st.parsed.errors[0], hint: getAgentConfig(st.agentType).installHint });
  }
}

// Patterns that indicate the agent is waiting for user confirmation or input
const ACTION_REQUIRED_PATTERNS = [
  /\?\s*\[y\/n\]/i,
  /\?\s*\(yes\/no\)/i,
  /\[y\/n\]\s*\?/i,
  /confirm/i,
  /proceed/i,
  /password/i,
  /passphrase/i,
  /enter\s+your\s+name/i,
  /select\s+an\s+option/i,
];

function detectActionRequired(buffer: string): boolean {
  const clean = stripAnsi(buffer);
  const lines = clean.split(/\r?\n/);
  const lastLine = lines[lines.length - 1]?.trim() || '';
  if (!lastLine) return false;
  return ACTION_REQUIRED_PATTERNS.some(re => re.test(lastLine));
}

// Track which terminals have broadcast terminal:ready (first data chunk)
const terminalReadySent = new Set<string>();
const readyTimeouts = new Map<string, ReturnType<typeof setTimeout>>();

function armTerminalReadyFallback(id: string) {
  const timer = setTimeout(() => {
    if (!terminalReadySent.has(id)) {
      terminalReadySent.add(id);
      broadcast('terminal:ready', id);
    }
    readyTimeouts.delete(id);
  }, 3000);
  readyTimeouts.set(id, timer);
}

function clearTerminalReadyFallback(id: string) {
  const timer = readyTimeouts.get(id);
  if (timer) {
    clearTimeout(timer);
    readyTimeouts.delete(id);
  }
}

function clearAgentTimeout(terminalId: string) {
  const st = agentStates.get(terminalId);
  // Clears BOTH the 6s force-ready backstop and the 15s error timer — startAgentTimeout
  // stashes them in separate fields so neither can survive a successful ready.
  if (st?.timeoutHandle) {
    clearTimeout(st.timeoutHandle);
    st.timeoutHandle = undefined;
  }
  if (st?.errorTimeoutHandle) {
    clearTimeout(st.errorTimeoutHandle);
    st.errorTimeoutHandle = undefined;
  }
}

// Error patterns for diagnoseAgentFailure
const ERROR_PATTERNS: Array<{ re: RegExp; reason: string }> = [
  { re: /is not recognized as (?:the name of )?a?\s*cmdlet/i, reason: 'not-recognized' },
  { re: /command not found/i, reason: 'not-recognized' },
  { re: /No such file or directory/i, reason: 'not-recognized' },
];

function diagnoseAgentFailure(id: string, agentType: string) {
  const st = agentStates.get(id);
  const tail = stripAnsi((st?.dataBuffer ?? '')).slice(-500);
  const cfg = getAgentConfig(agentType);

  for (const { re, reason } of ERROR_PATTERNS) {
    if (re.test(tail)) return { reason, detail: tail.trim(), hint: cfg.installHint };
  }
  const lastLine = tail.split(/\r?\n/).map((l) => l.trim()).filter(Boolean).pop() ?? '';
  if (looksLikeShell(lastLine)) {
    return { reason: 'dropped-to-shell', detail: `Terminal is at a shell prompt: "${lastLine}"`, hint: cfg.installHint };
  }
  return { reason: 'silent-timeout', detail: tail.trim() || 'No output captured.', hint: cfg.installHint };
}

function startAgentTimeout(id: string, agentType: string) {
  const st = agentStates.get(id);
  if (!st) return;

    // Blind force-ready REMOVED: we no longer flush the queue on a 5s timer without
    // verifying the TUI is actually listening (caused silent message loss). The
    // idle-settle heuristic (isTuiSettled) or the ready-regex drives readiness instead.

    // BACKSTOP: a bounded "last chance" force-ready. If the phase is still
    // 'launching' this far after spawn, the heuristics above did not fire — and
    // the consequence of staying in 'launching' is that agent:send returns
    // {queued:true, written:false} and the user's prompt is silently swallowed
    // forever. A late write that the TUI ignores is recoverable (the write
    // verifier retries, then surfaces agent:write-failed); a swallowed prompt is
    // not. Only fires if the PTY produced real output, so a dead spawn still
    // falls through to the 15s error timeout below.
    const backstop = setTimeout(() => {
        const cur = agentStates.get(id);
        if (!cur || cur.phase !== 'launching') return;
        if (cur.dataBuffer.length < 150) return;
        console.warn(`[AGENT-READY] Force-ready backstop fired for ${id} (${agentType}) — settle heuristics did not fire; flushing pending writes.`);
        markAgentReady(id, cur);
    }, 6000);
    st.timeoutHandle = backstop;

    // Full error timeout at 15s (reduced from 30s since we no longer blind-force at 5s)
    const timer = setTimeout(() => {
        clearAgentTimeout(id);
        if (agentStates.get(id)?.phase !== 'launching') return;
    const diag = diagnoseAgentFailure(id, agentType);
    for (const win of electron_1.BrowserWindow.getAllWindows()) {
      if (!win.isDestroyed()) {
        try { safeSend(win, 'agent:timeout', { terminalId: id, agentType }); } catch {}
        try { safeSend(win, 'agent:init-error', { terminalId: id, agentType, ...diag }); } catch {}
      }
    }
        failPendingWrites(id);
    }, 15000);
    st.errorTimeoutHandle = timer;
}

// Broadcast helper — send to all windows with disposal-safe pattern
function broadcast(event: string, ...args: any[]) {
  for (const win of electron_1.BrowserWindow.getAllWindows()) {
    if (!win.isDestroyed()) {
      try { safeSend(win, event, ...args); } catch {}
    }
  }
}

// ========== Per-terminal resource stats (RAM / CPU / lag) — realtime ==========
// Samples memory + CPU for each terminal's PTY process tree using built-in OS
// tools (no external deps). Emits 'terminal:resource-stats' to all windows.
const __cpuPrev = new Map(); // pid -> { cpuSec, ts } for Windows CPU delta
let __eventLoopLastTick = Date.now();
let __eventLoopLagMs = 0;
setInterval(() => {
  const now = Date.now();
  __eventLoopLagMs = Math.max(0, now - __eventLoopLastTick - 1000);
  __eventLoopLastTick = now;
}, 1000);

function __collectProcSnapshotUnix() {
  return new Promise((resolve) => {
    try {
      const cp = require('child_process');
      cp.execFile('ps', ['-eo', 'pid=,ppid=,rss=,pcpu='], { maxBuffer: 16 * 1024 * 1024 }, (err, stdout) => {
        const map = new Map();
        if (!err && stdout) {
          for (const line of String(stdout).split('\n')) {
            const parts = line.trim().split(/\s+/);
            if (parts.length >= 4) {
              const pid = parseInt(parts[0], 10);
              const ppid = parseInt(parts[1], 10);
              const rssKb = parseInt(parts[2], 10);
              const cpuPct = parseFloat(parts[3]);
              if (!isNaN(pid)) map.set(pid, { ppid: ppid || 0, rssKb: rssKb || 0, cpuPct: isNaN(cpuPct) ? 0 : cpuPct });
            }
          }
        }
        resolve(map);
      });
    } catch (e) { resolve(new Map()); }
  });
}

function __collectProcSnapshotWin() {
  return new Promise((resolve) => {
    try {
      const cp = require('child_process');
      const psCmd = "Get-CimInstance Win32_Process | Select-Object ProcessId,ParentProcessId,WorkingSetSize,@{N='Cpu';E={(Get-Process -Id $_.ProcessId -ErrorAction SilentlyContinue).CPU} } | ConvertTo-Csv -NoTypeInformation";
      cp.execFile('powershell.exe', ['-NoProfile', '-NonInteractive', '-Command', psCmd], { maxBuffer: 32 * 1024 * 1024, windowsHide: true }, (err, stdout) => {
        const map = new Map();
        if (!err && stdout) {
          const now = Date.now();
          for (const line of String(stdout).split(/\r?\n/)) {
            if (!line) continue;
            if (line.indexOf('WorkingSetSize') !== -1) continue;
            const cols = line.split(',').map((c) => c.replace(/^"|"$/g, ''));
            if (cols.length < 3) continue;
            const pid = parseInt(cols[0], 10);
            const ppid = parseInt(cols[1], 10);
            const ws = parseInt(cols[2], 10);
            if (isNaN(pid)) continue;
            const cpuSec = cols[3] !== undefined && cols[3] !== '' ? parseFloat(cols[3]) : NaN;
            let cpuPct = 0;
            if (!isNaN(cpuSec)) {
              const prev = __cpuPrev.get(pid);
              if (prev && now > prev.ts) cpuPct = Math.max(0, ((cpuSec - prev.cpuSec) / ((now - prev.ts) / 1000)) * 100);
              __cpuPrev.set(pid, { cpuSec, ts: now });
            }
            map.set(pid, { ppid: ppid || 0, rssKb: Math.round((ws || 0) / 1024), cpuPct });
          }
        }
        resolve(map);
      });
    } catch (e) { resolve(new Map()); }
  });
}

function __collectProcSnapshot() {
  return process.platform === 'win32' ? __collectProcSnapshotWin() : __collectProcSnapshotUnix();
}

function __sumProcessTree(rootPid, snap) {
  let rssKb = 0;
  let cpuPct = 0;
  const stack = [rootPid];
  const seen = new Set();
  while (stack.length) {
    const cur = stack.pop();
    if (seen.has(cur)) continue;
    seen.add(cur);
    const info = snap.get(cur);
    if (info) { rssKb += info.rssKb; cpuPct += info.cpuPct; }
    for (const [pid, i] of snap) { if (i.ppid === cur && !seen.has(pid)) stack.push(pid); }
  }
  return { rssKb, cpuPct };
}

let __resourceStatsBusy = false;
async function __sampleTerminalStats() {
  if (__resourceStatsBusy) return;
  const terms = terminalManager.terminals;
  if (!terms || terms.size === 0) return;
  __resourceStatsBusy = true;
  try {
    const snap = await __collectProcSnapshot();
    const alivePids = new Set(snap.keys());
    for (const pid of Array.from(__cpuPrev.keys())) { if (!alivePids.has(pid)) __cpuPrev.delete(pid); }
    const out = {};
    for (const [id, t] of terms) {
      const pid = t && t.pid;
      if (!pid || !snap.has(pid)) { out[id] = { pid: pid || null, alive: false, memMB: 0, cpuPct: 0, eventLoopLagMs: __eventLoopLagMs, ts: Date.now() }; continue; }
      const summed = __sumProcessTree(pid, snap);
      out[id] = {
        pid,
        alive: true,
        memMB: Math.round((summed.rssKb / 1024) * 10) / 10,
        cpuPct: Math.round(summed.cpuPct * 10) / 10,
        eventLoopLagMs: __eventLoopLagMs,
        ts: Date.now(),
      };
    }
    broadcast('terminal:resource-stats', out);
  } catch (e) {
    // non-fatal: sampling should never crash the app
  } finally {
    __resourceStatsBusy = false;
  }
}

let __resourceStatsTimer = null;
function __startResourceStatsSampler() {
  if (__resourceStatsTimer) return;
  __resourceStatsTimer = setInterval(() => { __sampleTerminalStats().catch(() => {}); }, 3000);
  if (__resourceStatsTimer && __resourceStatsTimer.unref) __resourceStatsTimer.unref();
}
__startResourceStatsSampler();

electron_1.ipcMain.handle('terminal:get-resource-stats', async () => {
  await __sampleTerminalStats();
  return { success: true };
});

electron_1.ipcMain.handle('terminal:get-system-stats', async () => {
  try {
    const os = require('os');
    const { execSync } = require('child_process');
    const totalMem = os.totalmem();
    const freeMem = os.freemem();
    const cpus = os.cpus();
    let gpuName = 'Unknown';
    let gpuMemMB = 0;
    try {
      if (process.platform === 'win32') {
        const raw = execSync('wmic path win32_VideoController get name,AdapterRAM /format:csv', { encoding: 'utf-8', timeout: 3000 });
        const lines = raw.trim().split('\n').filter((l: string) => l.includes(','));
        if (lines.length > 0) {
          const parts = lines[lines.length - 1].trim().split(',');
          gpuMemMB = Math.round((parseInt(parts[1]) || 0) / 1024 / 1024);
          gpuName = parts[2] || 'Unknown';
        }
      } else if (process.platform === 'darwin') {
        const raw = execSync('system_profiler SPDisplaysDataType -json 2>/dev/null | python3 -c "import sys,json; d=json.load(sys.stdin); sp=d.get(\'spprocessors\',d.get(\'SPDisplaysDataType\',[])); print(sp[0].get(\'spprocessors_model\',\'Unknown\') if sp else \'Unknown\')"', { encoding: 'utf-8', timeout: 5000 });
        gpuName = raw.trim() || 'Unknown';
      } else {
        const raw = execSync('lspci 2>/dev/null | grep -i vga', { encoding: 'utf-8', timeout: 3000 });
        gpuName = raw.trim().replace(/.*: /, '') || 'Unknown';
      }
    } catch { /* GPU detection not critical */ }
    return {
      success: true,
      data: {
        totalMemMB: Math.round(totalMem / 1024 / 1024),
        freeMemMB: Math.round(freeMem / 1024 / 1024),
        usedMemMB: Math.round((totalMem - freeMem) / 1024 / 1024),
        memPct: Math.round(((totalMem - freeMem) / totalMem) * 100) / 100,
        cpuCount: cpus.length,
        cpuModel: cpus[0]?.model || 'Unknown',
        uptime: Math.floor(os.uptime()),
        platform: process.platform,
        arch: process.arch,
        gpuName,
        gpuMemMB,
      }
    };
  } catch (e: any) {
    return { success: false, error: e.message };
  }
});

// Retry agent init — re-sends agent:ready for a terminal that timed out
electron_1.ipcMain.handle('retry-agent-init', async (_event, terminalId: string, agentType: string) => {
  try {
    const { BrowserWindow } = require('electron');
    const windows = BrowserWindow.getAllWindows();
    for (const win of windows) {
      if (!win.isDestroyed()) {
        safeSend(win, 'agent:ready', { terminalId });
      }
    }
    return { success: true };
  } catch (error: any) {
    return { success: false, error: error.message };
  }
});

// Per-terminal accumulated output between prompts (for action/metadata parsing)
const terminalResponseBuffers = new Map<string, string>();

// Parse agent output for ## Session Metadata and ## Actions blocks
function parseTerminalOutput(terminalId: string, output: string) {
    if (!db || !output || !output.trim()) return;
    try {
        const sessionRow = db.prepare('SELECT id, project_id FROM terminal_sessions WHERE terminal_id = ? ORDER BY created_at DESC LIMIT 1').get(terminalId) as any;
        if (!sessionRow) return;
        const sessionId = sessionRow.id;
        const actor = 'ai:terminal';

        // Parse session metadata
        const meta = parseSessionMetadata(output);
        if (meta) {
            const missingFields: string[] = [];
            const updates: string[] = [];
            const params: any[] = [];
            if (meta.title) { updates.push('topic = ?'); params.push(meta.title); }
            else missingFields.push('title');
            if (meta.description) { updates.push('description = ?'); params.push(meta.description); }
            if (meta.status) { updates.push('status = ?'); params.push(meta.status); }
            else missingFields.push('status');
            if (meta.productArea) { updates.push('product_area = ?'); params.push(meta.productArea); }
            if (meta.category) { updates.push('category = ?'); params.push(meta.category); }
            else missingFields.push('category');

            // Validate: emit feedback if critical fields missing
            if (missingFields.length > 0) {
                const feedback = `[SYSTEM: Session metadata incomplete — missing: ${missingFields.join(', ')}. Expected format: title, status, category, productArea, description. Please re-emit the block with all fields.]`;
                try { terminalManager.write(terminalId, feedback + '\r\n'); } catch {}
            }
            if (meta.category) { updates.push('category_confirmed = 1'); }
            if (updates.length > 0) {
                params.push(sessionId);
                db.prepare(`UPDATE terminal_sessions SET ${updates.join(', ')} WHERE id = ?`).run(...params);
                const tags: string[] = [];
                if (meta.category) tags.push(`category:${meta.category}`);
                if (meta.status) tags.push(`status:${meta.status}`);
                if (meta.productArea) tags.push(`area:${meta.productArea}`);
                if (tags.length > 0) {
                    db.prepare('UPDATE terminal_sessions SET auto_tags = ? WHERE id = ?').run(JSON.stringify(tags), sessionId);
                }
                const { BrowserWindow } = require('electron');
                const windows = BrowserWindow.getAllWindows();
                for (const win of windows) {
                    if (!win.isDestroyed()) {
                        safeSend(win, 'session-metadata-updated', { sessionId, metadata: meta, autoTags: tags });
                    }
                }
            }
        }

        // Parse and execute actions
        parseAndExecuteActions(output, sessionId, actor, terminalId);

        // Collaborative Debug — BUG-OWNER pattern detection
        const bugOwnerRegex = /BUG-OWNER:\s*(yes|no)\s*(?:-?\s*reason:\s*(.+?))?\s*(?:-?\s*session:\s*(\S+))?/i;
        const bugOwnerMatch = output.match(bugOwnerRegex);
        if (bugOwnerMatch) {
            handleBugOwnerResponse({
                terminalId,
                sessionId,
                agent: actor,
                response: bugOwnerMatch[1].toLowerCase() as 'yes' | 'no',
                reason: bugOwnerMatch[2]?.trim(),
                claimedSessionId: bugOwnerMatch[3]?.trim(),
            });
        }
    } catch (e) {
        console.error('[Terminal] parseTerminalOutput error:', e);
    }
}

// ── Collaborative Debug — Bug Owner Response Handler ──
const activeBugDispatches = new Map<string, { bugReportId: string; terminalIds: Set<string> }>();

function handleBugOwnerResponse(response: {
    terminalId: string;
    sessionId: string;
    agent: string;
    response: 'yes' | 'no';
    reason?: string;
    claimedSessionId?: string;
}) {
    if (!db) return;
    try {
        // Find the most recent pending bug report that this terminal was dispatched to
        const pending = db.prepare("SELECT * FROM bug_reports WHERE status = 'pending' ORDER BY created_at DESC LIMIT 5").all() as any[];
        let target: any = null;
        for (const p of pending) {
            const responses: any[] = JSON.parse(p.agent_responses || '[]');
            if (!responses.find((r: any) => r.terminalId === response.terminalId)) {
                target = p;
                break;
            }
        }
        if (!target) return;

        const responses: any[] = JSON.parse(target.agent_responses || '[]');
        const entry = {
            terminalId: response.terminalId,
            sessionId: response.sessionId,
            agent: response.agent,
            response: response.response,
            reason: response.reason || '',
            respondedAt: new Date().toISOString(),
        };
        responses.push(entry);
        db.prepare('UPDATE bug_reports SET agent_responses = ?, updated_at = CURRENT_TIMESTAMP WHERE id = ?').run(JSON.stringify(responses), target.id);

        if (response.response === 'yes' && response.reason) {
            // Auto-create a Problem
            try {
                const { BrowserWindow } = require('electron');
                const windows = BrowserWindow.getAllWindows();
                const projectRow = db.prepare('SELECT project_id FROM terminal_sessions WHERE id = ?').get(response.sessionId) as any;
                const projectId = projectRow?.project_id;
                const projectPath = projectId ? getProjectPath(projectId) : undefined;

                const ProblemsServiceModule = require('./services/ProblemsService');
                const ProblemsService = ProblemsServiceModule.ProblemsService || ProblemsServiceModule;
                const ps = new ProblemsService(projectPath || '', projectId);
                const problem = ps.createProblem({
                    title: `[Auto] ${response.agent}: ${response.reason}`,
                    description: (target as any).error_text || response.reason,
                    category: 'bug',
                    priority: 'medium',
                });

                db.prepare("UPDATE bug_reports SET linked_problem_id = ?, status = 'identified', updated_at = CURRENT_TIMESTAMP WHERE id = ?").run(String(problem.id), target.id);

                for (const win of windows) {
                    if (!win.isDestroyed()) {
                        safeSend(win, 'context-changed', { type: 'problem', action: 'created', entity: { id: String(problem.id), title: problem.title, status: problem.status } });
                        safeSend(win, 'context-changed', { type: 'bug_report', action: 'updated', entity: { id: target.id, status: 'identified', linkedProblemId: String(problem.id) } });
                    }
                }

                // Notify the claiming agent
                try { terminalManager.write(response.terminalId, `[System] Your BUG-OWNER claim has been registered. Linked Problem: #${problem.id}.\n`); } catch {}
            } catch (e2) {
                console.error('[BugReport] Failed to auto-create problem:', e2);
            }
        }

        // Check if all dispatched terminals have responded
        const allSessions = db.prepare("SELECT terminal_id FROM terminal_sessions WHERE project_id = ? AND terminal_id IS NOT NULL").all((target as any).project_id) as any[];
        const allResponded = allSessions.every((s: any) =>
            responses.some((r: any) => r.terminalId === s.terminal_id)
        );
        if (allResponded) {
            const anyYes = responses.some((r: any) => r.response === 'yes');
            const newStatus = anyYes ? 'identified' : 'not_my_issue';
            db.prepare('UPDATE bug_reports SET status = ?, updated_at = CURRENT_TIMESTAMP WHERE id = ?').run(newStatus, target.id);
        }
    } catch (e) {
        console.error('[BugReport] handleBugOwnerResponse error:', e);
    }
}

// ── AI Task Completion Tracking ──
const pendingCompletions = new Set<string>();

function markTaskCompleted(terminalId: string) {
    if (!db) return;
    try {
        const { BrowserWindow } = require('electron');
        const sid = getSessionIdForTerminal(terminalId);
        if (!sid) return;
        const row = db.prepare('SELECT id FROM terminal_messages WHERE session_id = ? AND status = ? ORDER BY created_at ASC LIMIT 1').get(sid, 'in_progress') as any;
        if (row) {
            db.prepare(`UPDATE terminal_messages SET status = 'completed' WHERE id = ?`).run(row.id);
            const windows = BrowserWindow.getAllWindows();
            for (const win of windows) {
                if (!win.isDestroyed()) {
                    safeSend(win, 'ai-task:updated', { terminalId, messageId: row.id, status: 'completed' });
                }
            }
        }
    } catch (_e) { /* silent */ }
}

// Inline node-pty based TerminalManager
const terminalManager = {
  terminals: new Map(),
  intentionalKills: new Set<string>(),
  spawnTimes: new Map<string, number>(),
  // Relay support: track per-terminal data subscribers for unsubscribe
  dataSubscribers: new Map<string, Set<(d: string) => void>>(),
  has(id: string) { return this.terminals.has(id) },
  onData(id: string, cb: (d: string) => void): () => void {
    // Register the callback on the PTY
    const t = this.terminals.get(id);
    if (t) t.pty.onData(cb);
    // Track for unsubscribe
    if (!this.dataSubscribers.has(id)) this.dataSubscribers.set(id, new Set());
    this.dataSubscribers.get(id)!.add(cb);
    return () => {
      this.dataSubscribers.get(id)?.delete(cb);
      // Note: node-pty onData returns a disposable; we can't truly unsubscribe
      // from the PTY itself, but we stop forwarding by removing from our set.
      // The relay checks ws.readyState before sending, so a stale callback is harmless.
    };
  },
  spawn(id: string, cwd: string, cols: number = 80, rows: number = 24) {
    try {
      console.log('[TerminalManager] spawn called:', id, 'cwd:', cwd, 'has:', this.terminals.has(id), 'existing keys:', Array.from(this.terminals.keys()));
      if (this.terminals.has(id)) {
        console.log('[TerminalManager] DEDUPE KILL for:', id);
        this.kill(id);
      }
      const os = require('os');
      const fs = require('fs');
      const pty = require('node-pty');
      const shell = process.platform === 'win32' ? (process.env.COMSPEC || 'powershell.exe') : (process.env.SHELL || '/bin/bash');
      let workingDir = cwd && cwd.length > 0 ? cwd : os.homedir();
      try { if (!fs.existsSync(workingDir)) { workingDir = os.homedir(); } } catch {}
      console.log('[TerminalManager] spawning shell:', shell, 'in', workingDir);
      const proc = pty.spawn(shell, [], { name: 'xterm-256color', cols, rows, cwd: workingDir, env: process.env });
      this.spawnTimes.set(id, Date.now());
      console.log('[TerminalManager] PTY spawned, pid:', proc.pid);
      const ip: any = {
        write: (data: string) => proc.write(data),
        resize: (c: number, r: number) => proc.resize(c, r),
        kill: () => proc.kill(),
        onData: (cb: (d: string) => void) => proc.onData(cb),
        onExit: (cb: (code: number, sig: string) => void) => proc.onExit(cb),
      };
      this.terminals.set(id, { id, pty: ip, cwd, pid: proc.pid });
      console.log('[TerminalManager] terminal stored:', id, 'total terminals:', this.terminals.size);
      return { success: true };
    } catch (err: any) {
      console.error('[TerminalManager] Spawn error:', err.message);
      return { success: false, error: err.message };
    }
  },
  write(id: string, data: string) {
    const t = this.terminals.get(id);
    if (t) { t.pty.write(data); return true; }
    return false;
  },
  resize(id: string, cols: number, rows: number) {
    const t = this.terminals.get(id);
    if (t) { t.pty.resize(cols, rows); return true; }
    return false;
  },
  kill(id: string) {
    const t = this.terminals.get(id);
    if (t) { console.log('[TerminalManager] KILL:', id); this.intentionalKills.add(id); this.spawnTimes.delete(id); this.dataSubscribers.delete(id); try { t.pty.kill(); } catch {} this.terminals.delete(id); terminalMessageCounts.delete(id); releaseAllLocksForTerminal(id); clearTerminalReadyFallback(id); terminalReadySent.delete(id); return true; }
    console.log('[TerminalManager] KILL: no terminal for', id);
    return false;
  },
  getDataHandler(id: string, cb: (d: string) => void) {
    const t = this.terminals.get(id);
    if (t) t.pty.onData(cb);
  },
  getExitHandler(id: string, cb: (code: number, sig: string) => void) {
    const t = this.terminals.get(id);
    if (t) t.pty.onExit((result) => cb(result.exitCode, result.signal?.toString() ?? ''));
  }
};

// ── File Lock Manager (cross-session conflict detection) ─────────
const LOCK_TTL_MS = 60000;
const fileLocks = new Map<string, { terminalId: string; sessionId: string | null; timestamp: number; action: string }>();

function acquireLock(filePath: string, terminalId: string, sessionId: string | null, action: string = 'edit'): { acquired: boolean; heldBy?: string } {
  const existing = fileLocks.get(filePath);
  if (existing) {
    if (existing.terminalId === terminalId) return { acquired: true }; // same terminal = re-lock
    if (Date.now() - existing.timestamp > LOCK_TTL_MS) { // expired
      fileLocks.delete(filePath);
    } else {
      return { acquired: false, heldBy: existing.terminalId };
    }
  }
  fileLocks.set(filePath, { terminalId, sessionId, timestamp: Date.now(), action });
  return { acquired: true };
}

function releaseLock(filePath: string, terminalId: string): boolean {
  const existing = fileLocks.get(filePath);
  if (existing && existing.terminalId === terminalId) {
    fileLocks.delete(filePath);
    return true;
  }
  return false;
}

function releaseAllLocksForTerminal(terminalId: string): void {
  for (const [path, lock] of fileLocks) {
    if (lock.terminalId === terminalId) fileLocks.delete(path);
  }
}

function getLocksForFile(filePath: string): { terminalId: string; sessionId: string | null; timestamp: number; action: string } | undefined {
  const lock = fileLocks.get(filePath);
  if (lock && Date.now() - lock.timestamp > LOCK_TTL_MS) {
    fileLocks.delete(filePath);
    return undefined;
  }
  return lock;
}

function getAllLocks(): Array<{ filePath: string; terminalId: string; sessionId: string | null; timestamp: number; action: string }> {
  const now = Date.now();
  for (const [path, lock] of fileLocks) {
    if (now - lock.timestamp > LOCK_TTL_MS) fileLocks.delete(path);
  }
  return Array.from(fileLocks.entries()).map(([filePath, lock]) => ({ filePath, ...lock }));
}

// Periodic lock sweep
setInterval(() => {
  const now = Date.now();
  for (const [path, lock] of fileLocks) {
    if (now - lock.timestamp > LOCK_TTL_MS) fileLocks.delete(path);
  }
}, LOCK_TTL_MS);

// ── File edit detection ──────────────────────────────────────────
function detectEditsInOutput(terminalId: string, output: string) {
  if (!output || output.trim().length < 20) return;

  // Look up session_id from DB
  let sessionId: string | null = null;
  if (db) {
    try {
      const binding = db.prepare('SELECT session_id FROM terminal_bindings WHERE terminal_id = ?').get(terminalId) as any;
      sessionId = binding?.session_id || null;
    } catch {}
  }

  // Look for file write patterns in agent output
  const filePattern = /(?:wrote|saved|written|modified|created|updated|writes? to|edits?)\s+`?(?:\.\/)?([^\s`'"()]+\.[a-zA-Z]+)/gi;
  let match: RegExpExecArray | null;
  const seen = new Set<string>();

  while ((match = filePattern.exec(output)) !== null) {
    let filePath = match[1].replace(/[`'"]/g, '').trim();
    if (!filePath || filePath.length > 200 || seen.has(filePath)) continue;
    seen.add(filePath);

    const result = acquireLock(filePath, terminalId, sessionId);
    if (db) {
      try {
        db.prepare('INSERT INTO touched_files (terminal_id, session_id, file_path, action) VALUES (?, ?, ?, ?)')
          .run(terminalId, sessionId, filePath, result.acquired ? 'edit' : 'conflict');
      } catch {}
    }
    if (!result.acquired && result.heldBy) {
      const windows = require('electron').BrowserWindow.getAllWindows();
      for (const win of windows) {
        if (!win.isDestroyed()) {
          safeSend(win, 'file:conflict', {
            filePath,
            requestingTerminal: terminalId,
            lockingTerminal: result.heldBy,
            sessionId,
            timestamp: Date.now(),
          });
        }
      }
    }
  }
}

electron_1.ipcMain.handle('terminal:create', async (_event, id: string, cwd: string, cols: number, rows: number, agentType?: string) => {
    try {
        const result = terminalManager.spawn(id, cwd, cols, rows);
        if (result.success) {
            // Always set up agent state — use DEFAULT_AGENT if none specified
            // This ensures agent:send works even for "Open Terminal" button spawns
            const type = (agentType && agentType.trim().length > 0) ? agentType : DEFAULT_AGENT;
            clearAgentTimeout(id);
            const spawnedPid = (terminalManager.terminals.get(id) as any)?.pid;
            agentStates.set(id, { agentType: type, phase: 'launching', dataBuffer: '', idleSeq: 0, launchStartedAt: Date.now(), pendingWrites: [], sessionIdCaptured: false, spawnedPid });
            startAgentTimeout(id, type);
            armTerminalReadyFallback(id);

            // [STATE-SPOKE] Auto-create spoke file for this session
            try {
                const sessionId = `${type}-${id.slice(0, 6)}-${Date.now().toString(36).slice(-4)}`;
                const spokeDir = getAgentStateDir(cwd);
                const spokePath = path.join(spokeDir, `${sessionId}.md`);
                const templatePath = path.join(spokeDir, '_template.md');
                if (!require('fs').existsSync(spokePath)) {
                    const template = require('fs').readFileSync(templatePath, 'utf-8');
                    const now = new Date().toISOString();
                    const spoke = template
                        .replace(/\{SESSION_ID\}/g, sessionId)
                        .replace(/\{AGENT_TYPE\}/g, type)
                        .replace(/\{TERMINAL_ID\}/g, id)
                        .replace(/\{PROJECT_PATH\}/g, cwd || '')
                        .replace(/\{CYCLE_NUMBER\}/g, '1')
                        .replace(/\{ISO_TIMESTAMP\}/g, now)
                        .replace(/\{working\|idle\|error\|completed\}/g, 'working')
                        .replace(/\{what you are doing this cycle\}/g, `Initializing ${type} session`)
                        .replace(/\{active task 1\}/g, 'Starting agent session')
                        .replace(/\{task completed this cycle\}/g, 'Session spawned')
                        .replace(/\{what happens next\}/g, 'Waiting for agent to be ready')
                        .replace(/\{optional freeform context\}/g, '')
                        .replace(/\{role\}/g, 'Initializing')
                        .replace(/\{status\}/g, 'working')
                        .replace(/\{task\}/g, 'Initializing')
                        .replace(/\{next\}/g, 'Agent startup');
                    require('fs').writeFileSync(spokePath, spoke, 'utf-8');
                }
            } catch {}

            // [FLOW-CONTROL] Batch same-tick PTY data chunks into a single IPC message.
            // Node-pty fires onData per chunk; high-volume agent streaming can fire dozens
            // of small chunks per tick. Without batching, each chunk is a separate IPC call,
            // flooding the renderer's event loop (documented failure mode in VS Code terminal).
            const dataBatchBuffers = new Map<string, string>();
            const dataBatchTimers = new Map<string, ReturnType<typeof setTimeout>>();

            // [MSG-HYGIENE] Buffer PTY output per terminal; flush CLEANED transcript
            // fragments to terminal_messages only when the agent transitions busy->ready.
            // Never store raw ANSI chunks.
            const pendingTranscript = new Map<string, string>();
            function flushTranscriptToDb(terminalId: string) {
                const raw = pendingTranscript.get(terminalId);
                if (!raw) return;
                pendingTranscript.delete(terminalId);
                try {
                    const clean = stripAnsi(raw)
                        .replace(/\r\n/g, '\n')
                        .replace(/\n{3,}/g, '\n\n')
                        .trim();
                    if (clean.length < 10) return;
                    if (!db) return;
                    const sid = (db.prepare('SELECT id FROM terminal_sessions WHERE terminal_id = ? ORDER BY created_at DESC LIMIT 1').get(terminalId) as any)?.id;
                    if (!sid) return;
                    // Dedup: skip if identical to the last assistant row for this session
                    const last = db.prepare(
                        "SELECT content FROM terminal_messages WHERE session_id = ? AND role = 'assistant' ORDER BY created_at DESC LIMIT 1"
                    ).get(sid) as any;
                    if (last && last.content === clean) return;
                    db.prepare('INSERT INTO terminal_messages (session_id, role, content) VALUES (?, ?, ?)').run(sid, 'assistant', clean);
                } catch (_e) { /* non-fatal */ }
            }

            terminalManager.getDataHandler(id, function (data) {
                if (!terminalReadySent.has(id)) {
                    terminalReadySent.add(id);
                    clearTerminalReadyFallback(id);
                    broadcast('terminal:ready', id);
                }

                // Coalesce: append to buffer, schedule flush on next macrotask
                const existing = dataBatchBuffers.get(id) || '';
                dataBatchBuffers.set(id, existing + data);
                if (!dataBatchTimers.has(id)) {
                    dataBatchTimers.set(id, setImmediate(() => {
                        dataBatchTimers.delete(id);
                        const batched = dataBatchBuffers.get(id);
                        dataBatchBuffers.delete(id);
                        if (batched) broadcast('terminal:data', id, batched);
                    }) as any);
                }

                // [MSG-HYGIENE] Accumulate PTY output for cleaned flush (never store raw ANSI)
                const pt = pendingTranscript.get(id) || '';
                pendingTranscript.set(id, pt + data);

                const st = agentStates.get(id);
                if (!st) return;
                st.lastOutputAt = Date.now(); // Reset idle timer on every chunk
                st.dataBuffer += data;
                if (st.dataBuffer.length > 10000) st.dataBuffer = st.dataBuffer.slice(-5000);

                // [AGENT-PARSE] Incremental output parsing + session ID capture
                handleAgentOutputChunk(id, st, data);

                // [MEMORY-CAPTURE] Parse [save-memory] tags from agent output
                try {
                    const saveMemoryMatch = data.match(/\[save-memory\]\s*([^|]+)\s*\|\s*([^|]+)\s*\|\s*(.+)/i);
                    if (saveMemoryMatch) {
                        const content = saveMemoryMatch[3].trim();
                        memoryCapture.captureMemoryFromMessage(content, 'agent', id, undefined);
                    }
                    // Also capture self-reflection patterns
                    memoryCapture.captureMemoryFromMessage(data, 'agent', id, undefined);
                } catch {}

                // Accumulate agent output for parsing (only after ready)
                if (st.phase === 'ready' || st.phase === 'busy') {
                    const buf = terminalResponseBuffers.get(id) || '';
                    terminalResponseBuffers.set(id, buf + data);
                }

                const promptSeen = detectAgentPrompt(st.dataBuffer, st.agentType);
                const actionRequired = (st.parsed?.actionRequired) || detectActionRequired(st.dataBuffer);
                try { maybeBroadcastNotice(id); } catch (_e) { }

                // WRITE VERIFICATION: If we are busy and new data arrives, the TUI reacted to our write!
                if (st.phase === 'busy' && st.verifyTimeout) {
                    console.log(`[AGENT-VERIFY] Write confirmed via PTY reaction for ${id}`);
                    clearTimeout(st.verifyTimeout);
                    st.verifyTimeout = undefined;
                    // Mark the pending message as verified in DB (handled via broadcast to renderer/DB layer)
                    broadcast('agent:write-verified', { terminalId: id });
                    st.phase = 'ready';
                    st.idleSeq += 1;
                    flushPendingAgentWrites(id, st);
                    broadcast('agent:idle', { terminalId: id, seq: st.idleSeq });
                    broadcast('ai-task:updated', { terminalId: id, status: 'completed' });
                    return; // Skip further state checks for this chunk
                }

                if (st.phase === 'launching' && (detectAgentPrompt(st.dataBuffer, st.agentType) || isTuiSettled(st))) {
                    console.log(`[AGENT-SETTLE] TUI settled or regex matched for ${id}. Flushing queue.`);
                    flushTranscriptToDb(id);
                    markAgentReady(id, st);
                } else if ((st.phase === 'busy' || st.phase === 'attention') && promptSeen) {
                    st.phase = 'ready';
                    st.idleSeq += 1;
                    flushPendingAgentWrites(id, st);
                    broadcast('agent:idle', { terminalId: id, seq: st.idleSeq });
                    agentStatusBroadcast(id, st);
                    broadcast('ai-task:updated', { terminalId: id, status: 'completed' });
                } else if (st.phase === 'busy' && actionRequired) {
                    st.phase = 'attention';
                    agentStatusBroadcast(id, st);
                    broadcast('ai-task:updated', { terminalId: id, status: 'action_required' });
                } else if (st.phase === 'attention' && !actionRequired && data.length > 0) {
                    st.phase = 'busy';
                    agentStatusBroadcast(id, st);
                    broadcast('ai-task:updated', { terminalId: id, status: 'in_progress' });
                }

                if ((st.phase === 'ready' || st.phase === 'busy') && promptSeen) {
                    const output = terminalResponseBuffers.get(id) || '';
                    terminalResponseBuffers.set(id, '');
                    if (output.trim().length > 20) {
                        parseTerminalOutput(id, output);
                    }
                    detectEditsInOutput(id, output);
                }

                if ((st.phase === 'ready' || st.phase === 'busy') && pendingCompletions.has(id) && promptSeen) {
                    pendingCompletions.delete(id);
                    markTaskCompleted(id);
                }
            });

            terminalManager.getExitHandler(id, (exitCode: number, signal: string) => {
                clearAgentTimeout(id);
                failPendingWrites(id);
                const intentional = terminalManager.intentionalKills.has(id);
                const spawnTime = terminalManager.spawnTimes.get(id);
                const isRecentSpawn = spawnTime && (Date.now() - spawnTime < 2000);
                terminalManager.spawnTimes.delete(id);
                terminalManager.intentionalKills.delete(id);
                broadcast('terminal:exit', id, exitCode, signal, intentional || !!isRecentSpawn);
                flushTranscriptToDb(id);
            });
        }
        return result;
    } catch (err: any) {
        console.error('[DeskFlow] terminal:create error:', err.message);
        return { success: false, error: err.message };
    }
});

