electron_1.ipcMain.handle('agent:send', async (_event, terminalId: string, data: string, agentType?: string) => {
    const st = agentStates.get(terminalId);
    if (!st) {
        return { success: false, error: 'Agent session not found' };
    }
    const type = agentType || DEFAULT_AGENT;

    // [MEMORY-CAPTURE] Auto-capture memories from user messages
    try {
        const cycleNum = parseInt((await db?.prepare('SELECT COUNT(*) as c FROM terminal_messages WHERE session_id = ?').get(getSessionIdForTerminal(terminalId))?.c) || '0');
        memoryCapture.captureMemoryFromMessage(data, 'user', terminalId, cycleNum);
    } catch {}

    const recordPrompt = () => {
        if (!db || !data || data.trim().length < 1) return undefined;
        try {
            const sid = getSessionIdForTerminal(terminalId);
            if (!sid) return undefined;
            pendingCompletions.add(terminalId);
            const result = db.prepare('INSERT INTO terminal_messages (session_id, role, content, status) VALUES (?, ?, ?, ?)').run(sid, 'user', data, 'in_progress');
            vaultLogSafe({ source: 'terminal-agent', event: 'prompt', contextId: sid, role: 'user', payload: { text: data, agentType } });
            // [CONTEXT-BRAIN] Feed workspace agent prompts into the context brain
            try {
                const sessionRow = db.prepare('SELECT id, agent_type, topic FROM terminal_sessions WHERE id = ?').get(sid) as any;
                if (sessionRow) {
                    episodeWriters.writeTerminalEpisode({ id: sid, agent_type: sessionRow.agent_type, topic: sessionRow.topic }, data, 'user');
                }
            } catch (_e) { /* brain write is best-effort */ }
            return result;
        } catch (_e) { return undefined; }
    };
    const notifyTask = (messageId: number | bigint | undefined) => {
        try {
            const { BrowserWindow } = require('electron');
            const windows = BrowserWindow.getAllWindows();
            for (const win of windows) {
                if (!win.isDestroyed()) {
                    try {
                        safeSend(win, 'ai-task:updated', { terminalId, status: 'in_progress', messageId });
                    } catch (e) { /* silent */ }
                }
            }
        } catch (_e) { /* silent */ }
    };

    if (st.phase === 'launching' || st.phase === 'busy') {
        st.pendingWrites = st.pendingWrites || [];
        st.pendingWrites.push(data);
        const result = recordPrompt();
        if (result) notifyTask(result.lastInsertRowid);
        return { success: true, queued: true, written: false, verified: false };
    }
    const payload = buildAgentInputPayload(data, st.agentType || type);
    const success = terminalManager.write(terminalId, payload);
    if (success) {
        st.phase = 'busy';
        const result = recordPrompt();
        if (result) notifyTask(result.lastInsertRowid);

        // Start Verification Timer
        if (st.verifyTimeout) clearTimeout(st.verifyTimeout);
        st.verifyTimeout = setTimeout(() => {
            if (st.phase === 'busy') {
                console.warn(`[AGENT-VERIFY] Write unverified after 2.5s for ${terminalId}. Retrying...`);
                // Retry once: send a wake \r (in case input box lost focus) then payload
                terminalManager.write(terminalId, '\r');
                setTimeout(() => {
                    terminalManager.write(terminalId, payload);
                    // Final fail timer
                    st.verifyTimeout = setTimeout(() => {
                        if (st.phase === 'busy') {
                            console.error(`[AGENT-VERIFY] Retry failed for ${terminalId}. Marking error.`);
                            st.phase = 'error';
                            st.lastError = 'Write unverified: TUI did not react to input';
                            broadcast('agent:write-failed', { terminalId, reason: 'unverified-write' });
                        }
                    }, 2500);
                }, 100);
            }
        }, 2500);
        return { success: true, queued: false, written: true, verified: false };
    }
    return { success: false, error: 'PTY write failed' };
});

