electron_1.ipcMain.handle('assemble-context', async (_event, data: { projectId: string; problemIds?: string[]; requestIds?: string[]; tokenBudget?: number; topic?: string; sessionId?: string }) => {
  try {
    const parts = [];
    let totalChars = 0;
    const budget = data.tokenBudget || 4000;
    const maxChars = budget * 4;

    const problems = db.prepare('SELECT id, title, status, priority, category, description FROM workspace_problems WHERE project_id = ? ORDER BY created_at DESC').all(data.projectId) as any[];
    const requests = db.prepare('SELECT id, title, status, priority, description FROM workspace_requests WHERE project_id = ? ORDER BY created_at DESC').all(data.projectId) as any[];
    const sessions = db.prepare("SELECT id, topic, status, agent, agent_label, created_at FROM terminal_sessions WHERE project_id = ? AND status != 'cancelled' ORDER BY created_at DESC LIMIT 10").all(data.projectId) as any[];

    if (problems.length > 0) {
      const lines = ['## Active Problems\n'];
      for (const p of problems) {
        const line = `- **${p.id}**: ${p.title} (${p.status})`;
        if (totalChars + line.length > maxChars) break;
        lines.push(line);
        totalChars += line.length;
        if (totalChars + line.length > maxChars) break;
      }
      parts.push(lines.join('\n'));
    }

    if (requests.length > 0) {
      const lines = ['## Active Requests\n'];
      for (const r of requests) {
        const line = `- **${r.id}**: ${r.title} (${r.priority})`;
        if (totalChars + line.length > maxChars) break;
        lines.push(line);
        totalChars += line.length;
      }
      parts.push(lines.join('\n'));
    }

    if (sessions.length > 0) {
      const lines = ['## Recent Sessions\n'];
      for (const s of sessions) {
        const line = `- **${s.topic || 'Untitled'}** — ${s.agent_label || s.agent} (${s.status})`;
        if (totalChars + line.length > maxChars) break;
        lines.push(line);
        totalChars += line.length;
      }
      parts.push(lines.join('\n'));
    }

    const backupProtocol = [
        '## Backup & Safety Protocol',
        '- A full snapshot (database + project files) is taken automatically before this agent session started and every 30 min; you never need to create backups yourself.',
        '- If a change might need to be undone later (patch, fix packet, refactor): ASK the user for permission first, then create a physical backup in `agent/backups/<timestamp>-desc-pre/` and VERIFY it (file count + sizes) before editing.',
        '- NEVER run destructive git commands (git checkout/restore/reset --hard/clean).',
        '- The database is READ-ONLY for you: never modify %APPDATA%/RHEO/deskflow-data.db.',
        '- If something goes wrong, restore is a USER action in the Backup Center page — never restore files or DB yourself.',
        '- Mention any backup taken in your cycle report (ARTIFACTS).',
    ].join('\n');
    parts.push(backupProtocol);
    totalChars += backupProtocol.length;

    // [CONTEXT-BRAIN] Inject compact user context profile into workspace assembly
    try {
        const profile = userContextService.getProfile();
        if (profile) {
            const userLines: string[] = ['## User Context (auto-derived)'];
            if (profile.summary) {
                const line = '- Summary: ' + profile.summary;
                if (totalChars + line.length <= maxChars) { userLines.push(line); totalChars += line.length; }
            }
            const traits = Object.keys(profile.traits || {});
            if (traits.length > 0) {
                const line = '- Traits: ' + traits.map((k: string) => profile.traits[k].content).join(', ');
                if (totalChars + line.length <= maxChars) { userLines.push(line); totalChars += line.length; }
            }
            const interests = Object.keys(profile.interests || {});
            if (interests.length > 0) {
                const line = '- Interests: ' + interests.map((k: string) => profile.interests[k].content).join(', ');
                if (totalChars + line.length <= maxChars) { userLines.push(line); totalChars += line.length; }
            }
            const comm = Object.keys(profile.communicationStyle || {});
            if (comm.length > 0) {
                const line = '- Communication: ' + comm.map((k: string) => profile.communicationStyle[k].content).join(', ');
                if (totalChars + line.length <= maxChars) { userLines.push(line); totalChars += line.length; }
            }
            const highlights = profile.memoryHighlights || [];
            const corrections = highlights.filter((h: any) => h.source === 'signal' && h.importance > 0.5);
            if (corrections.length > 0 && totalChars + 120 <= maxChars) {
                userLines.push('- Important rules/corrections (follow these):');
                for (const h of corrections.slice(0, 3)) {
                    const line = '  - ' + h.content;
                    if (totalChars + line.length > maxChars) break;
                    userLines.push(line);
                    totalChars += line.length;
                }
            }
            if (userLines.length > 1) parts.push(userLines.join('\n'));
        }
    } catch (_e) { /* profile injection is best-effort */ }

    // [STATE-MD] Inject condensed state.md
    try {
      const projectDir = db.prepare('SELECT path FROM projects WHERE id = ?').get(data.projectId) as any;
      const statePath = require('path').join(projectDir?.path || '', 'agent', 'state.md');
      const fs = require('fs');
      if (fs.existsSync(statePath)) {
        const stateRaw = fs.readFileSync(statePath, 'utf-8');
        if (stateRaw && stateRaw.trim().length > 0) {
          const CAP = 1500;
          let stateMd = stateRaw;
          if (stateRaw.length > CAP) {
            const lines = stateRaw.split('\n');
            const headerLines: string[] = [];
            const dateSections: Array<{ header: string; lines: string[] }> = [];
            let currentSection: { header: string; lines: string[] } | null = null;
            for (const line of lines) {
              const isDateHeader = /^#{2,3}\s+\[?\d{4}-\d{2}-\d{2}/.test(line);
              if (isDateHeader) {
                if (currentSection) dateSections.push(currentSection);
                currentSection = { header: line, lines: [] };
              } else if (currentSection) {
                currentSection.lines.push(line);
              } else if (headerLines.length < 10) {
                headerLines.push(line);
              }
            }
            if (currentSection) dateSections.push(currentSection);
            const lastSections = dateSections.slice(-3);
            stateMd = headerLines.join('\n') + '\n\n';
            for (const s of lastSections) stateMd += s.header + '\n' + s.lines.join('\n') + '\n\n';
            if (stateMd.length > CAP) stateMd = stateMd.slice(0, CAP - 30) + '\n... [state.md truncated]';
          }
          const remainingBudget = maxChars - totalChars - 200;
          if (stateMd.length > 0 && stateMd.length < remainingBudget) {
            parts.push(`## Agent State\n${stateMd.trim()}`);
            totalChars += stateMd.length;
          }
        }
      }
    } catch (e) {
      console.warn('[assemble-context] state.md injection failed (non-fatal):', e);
    }

    // [CONTEXT-BRAIN] Topic-based memory restoration (assemble-context gap fix)
    try {
        let sessionTopic = '';
        if (data.sessionId) {
            try {
                const sess = db.prepare('SELECT topic FROM terminal_sessions WHERE id = ?').get(data.sessionId) as any;
                sessionTopic = (sess && sess.topic) || '';
            } catch { /* session lookup best-effort */ }
        }
        const queryTopic = (data.topic || sessionTopic || '').trim();
        if (queryTopic.length > 1) {
            const brainMd = (() => {
                try {
                    return contextFormatter.formatBrainContext(queryTopic, contextBrain.retrieve(queryTopic, ['keyword', 'graph']));
                } catch (e: any) {
                    console.warn('[assemble-context] Brain retrieval failed:', e.message);
                    return '';
                }
            })();
            const memoryMd = (() => {
                try {
                    const agentMemories = memoryStore.searchMemories(queryTopic);
                    const chatMemories = memoryRetrieval.getRelevantMemories(db, '', queryTopic, 3);
                    return contextFormatter.formatMemoryContext(agentMemories, chatMemories);
                } catch (e: any) {
                    console.warn('[assemble-context] Memory retrieval failed:', e.message);
                    return '';
                }
            })();
            const combinedMd = (brainMd + '\n' + memoryMd).trim();
            if (combinedMd.length > 0) {
                const remainingBudget = maxChars - totalChars - 200;
                if (remainingBudget > 100) {
                    const truncatedMd = contextFormatter.truncateToBudget(combinedMd, remainingBudget);
                    if (truncatedMd.length > 0) {
                        parts.push(truncatedMd);
                        totalChars += truncatedMd.length;
                    }
                }
            }
        }
    } catch (err: any) {
        console.warn('[assemble-context] Memory restoration block failed:', err.message);
    }

    const context = parts.join('\n\n---\n\n');

    return { success: true, context, tokensUsed: Math.ceil(totalChars / 4) };
  } catch (error: any) {
    return { success: false, error: error.message, context: '', tokensUsed: 0 };
  }
});

electron_1.ipcMain.handle('save-terminal-message', async (_event, data: {
    sessionId: string;
    role: 'user' | 'assistant' | 'system';
    content: string;
}) => {
    if (!db) return { success: false, error: 'No database' };
    try {
        const result = db.prepare(
            'INSERT INTO terminal_messages (session_id, role, content) VALUES (?, ?, ?)'
        ).run(data.sessionId, data.role, data.content);
        const messageId = result.lastInsertRowid;

        // Parse metadata from assistant messages
        if (data.role === 'assistant') {
            const meta = parseSessionMetadata(data.content);
            if (meta) {
                const updates: string[] = [];
                const params: any[] = [];
                if (meta.title) { updates.push('topic = ?'); params.push(meta.title); }
                if (meta.description) { updates.push('description = ?'); params.push(meta.description); }
                if (meta.status) { updates.push('status = ?'); params.push(meta.status); }
                if (meta.productArea) { updates.push('product_area = ?'); params.push(meta.productArea); }
                if (meta.category) { updates.push('category = ?'); params.push(meta.category); }
                if (meta.category) { updates.push('category_confirmed = 1'); }
                if (updates.length > 0) {
                    params.push(data.sessionId);
                    db.prepare(`UPDATE terminal_sessions SET ${updates.join(', ')} WHERE id = ?`).run(...params);

                    // Capture agent memory when a session completes (memory restoration loop)
                    if (meta.status === 'completed' && meta.title) {
                        try {
                            const content = `Session "${meta.title}"${meta.description ? ' - ' + meta.description : ''}`;
                            const dedupKey = ('session-completed:' + meta.title).toLowerCase().replace(/\s+/g, ' ').replace(/[^a-z0-9 ]/g, '').slice(0, 60).trim();
                            memoryStore.insertMemory({
                                id: crypto.randomUUID(),
                                content: content.slice(0, 500),
                                category: 'workflow',
                                tier: 'warm',
                                importance: 0.55,
                                accessCount: 0,
                                lastAccessedAt: Date.now(),
                                createdAt: Date.now(),
                                correctedAt: [Date.now()],
                                dedupKey,
                                source: { type: 'manual', sessionId: data.sessionId, cycleNumber: null, originalMessage: null },
                                decayRate: 0.01,
                                staleAfterDays: 90,
                            });
                        } catch (e: any) {
                            console.warn('Failed to capture agent memory on completion:', e.message);
                        }
                    }

                    // Generate auto-tags from metadata
                    const tags: string[] = [];
                    if (meta.category) tags.push(`category:${meta.category}`);
                    if (meta.status) tags.push(`status:${meta.status}`);
                    if (meta.productArea) tags.push(`area:${meta.productArea}`);
                    if (tags.length > 0) {
                        db.prepare('UPDATE terminal_sessions SET auto_tags = ? WHERE id = ?').run(JSON.stringify(tags), data.sessionId);
                    }
                    
                    // Notify renderer about metadata change
                    mainWindow?.webContents?.send('session-metadata-updated', {
                        sessionId: data.sessionId,
                        metadata: meta,
                        autoTags: tags,
                    });
                }
            }

            // Parse decisions, actions, status changes
            const parsedItems = parseMessageContent(data.content);
            const insertStmt = db.prepare(
                'INSERT INTO session_parsed_items (session_id, item_type, content, source_message_id) VALUES (?, ?, ?, ?)'
            );
            for (const item of parsedItems) {
                insertStmt.run(data.sessionId, item.item_type, item.content, messageId);
            }

            // Auto-create problems/requests from parsed items
            if (parsedItems.length > 0) {
                try {
                    const termRow2 = db.prepare('SELECT terminal_id FROM terminal_sessions WHERE id = ?').get(data.sessionId) as any;
                    if (termRow2?.terminal_id) {
                        const term = terminalManager.terminals.get(termRow2.terminal_id);
                        if (term?.cwd) {
                            const projectBaseDir = term.cwd;
                            let projectId: string | undefined;
                            try {
                                const projRow = db.prepare('SELECT id FROM projects WHERE path = ?').get(projectBaseDir) as any;
                                if (projRow) projectId = projRow.id;
                            } catch {}
                            const ps2 = new ProblemsService(projectBaseDir, projectId);
                            const rs2 = new RequestsService(projectBaseDir);
                            for (const item of parsedItems) {
                                if (item.item_type === 'action_item') {
                                    try {
                                        rs2.createRequest({
                                            title: item.content.substring(0, 80),
                                            description: `Auto-extracted from session ${data.sessionId}:\n\n${item.content}`,
                                            priority: 'medium',
                                            category: 'feature',
                                            sessionId: data.sessionId,
                                        });
                                    } catch (e) {
                                        console.error('[save-terminal-message] Failed to create request from parsed item:', e);
                                    }
                                }
                                if (item.item_type === 'status_change') {
                                    try {
                                        ps2.createProblem({
                                            title: item.content.substring(0, 80),
                                            description: `Auto-extracted from session ${data.sessionId}:\n\n${item.content}`,
                                            priority: 'medium',
                                            category: item.content.toLowerCase().includes('fixed') ? 'bug-fix' : 'task',
                                            sessionId: data.sessionId,
                                        });
                                    } catch (e) {
                                        console.error('[save-terminal-message] Failed to create problem from parsed item:', e);
                                    }
                                }
                            }
                        }
                    }
                } catch (e) {
                    console.error('[save-terminal-message] Failed to auto-create from parsed items:', e);
                }
            }

            // Parse and execute structured actions
            try {
                const termRow = db.prepare('SELECT terminal_id FROM terminal_sessions WHERE id = ?').get(data.sessionId) as any;
                parseAndExecuteActions(data.content, data.sessionId, 'ai:' + (getSessionAgent(data.sessionId) || 'unknown'), termRow?.terminal_id);
            } catch {}
        }

        return { success: true, id: messageId };
    } catch (err: any) {
        console.error('[DeskFlow] save-terminal-message error:', err.message);
        return { success: false, error: err.message };
    }
});

