// Generate AI categorization for apps/websites using OpenRouter API
electron_1.ipcMain.handle('generate-ai-categorization', async (event, items) => {
    try {
        const { buildChain: buildChainCat, runWithFallback: runWithFallbackCat } = require('./services/providers/router');
        const p = userPreferences || {};
        const pState = migrateProviderNames(JSON.parse(p.aiProviders || 'null')) || { providers: [], routing: { default: { providerId: 'auto', model: '' } } };
        const chain = buildChainCat(pState, 'category');
        if (!chain.length) {
            console.warn('[DeskFlow] No AI providers configured � cannot generate categories');
            event.sender.send('provider-chunk', { delta: null, done: true, error: 'No AI providers configured. Add a provider in Settings ? AI Assistant.', purpose: 'category' });
            return { changes: [], lockedSkipped: [] };
        }

        // Filter out locked items
        const lockedApps = categoryConfig.lockedApps || {};
        const lockedDomains = categoryConfig.lockedDomains || {};
        const lockedSkipped: string[] = [];
        const unlockedItems = items.filter((item: any) => {
            const isApp = !item.name.includes('.');
            const locks = isApp ? lockedApps : lockedDomains;
            if (locks[item.name]) {
                lockedSkipped.push(item.name);
                return false;
            }
            return true;
        });

        if (unlockedItems.length === 0) {
            console.log('[DeskFlow] All items are locked, skipping AI categorization');
            event.sender.send('provider-chunk', { delta: null, done: true, error: 'All items are locked � unlock some to generate categories.', purpose: 'category' });
            return { changes: [], lockedSkipped };
        }

        console.log(`[DeskFlow] Generating categories for ${unlockedItems.length} items (${lockedSkipped.length} locked skipped)...`);
        event.sender.send('provider-chunk', { delta: `Categorizing ${unlockedItems.length} item(s) using ${chain[0].provider.config.label}...`, providerId: chain[0].provider.config.id, purpose: 'category' });

        const itemsList = unlockedItems.map(i => `${i.name} (current: ${i.category})`).join(', ');
        
        const userPrompt = `Categorize these apps/websites into appropriate categories. Use these categories: IDE, AI Tools, Browser, Entertainment, Communication, Design, Productivity, Tools, Education, Developer Tools, Search Engine, News, Shopping, Social Media, Uncategorized, Other.

Items: ${itemsList}

Return ONLY a JSON array of objects with "name" and "category" keys.

Example format: [{"name": "app1", "category": "Productivity"}, {"name": "app2", "category": "Entertainment"}]`;

        console.log(`[DeskFlow] [AI-Categorize] PROMPT >>> ${userPrompt}`);
        event.sender.send('provider-chunk', { delta: null, prompt: userPrompt, providerId: chain[0].provider.config.id, purpose: 'category' });

        const { result, usedProviderId } = await runWithFallbackCat(chain, {
            systemPrompt: CATEGORY_SYSTEM_PROMPT,
            messages: [{ role: 'user', content: userPrompt }],
            maxTokens: 4000,
            temperature: 0.3,
        });

        const content = result.content;
        if (!content) {
            console.error('[DeskFlow] [AI-Categorize] No content in AI response');
            event.sender.send('provider-chunk', { delta: null, done: true, error: 'AI returned an empty response.', providerId: usedProviderId, purpose: 'category' });
            return { changes: [], lockedSkipped };
        }

        console.log('[DeskFlow] [AI-Categorize] RESPONSE >>>', content);
        event.sender.send('provider-chunk', { delta: null, done: true, providerId: usedProviderId, full: content, purpose: 'category' });

        const parsed = extractJsonFromResponse(content);
        // Build change objects with previous categories
        const changes = parsed.map((item: any) => {
            const original = items.find((i: any) => i.name === item.name);
            return {
                name: item.name,
                type: item.name.includes('.') ? 'domain' : 'app',
                previousCategory: original?.category || 'Other',
                newCategory: item.category
            };
        }).filter((c: any) => c.previousCategory !== c.newCategory); // Only include actual changes
        console.log('[DeskFlow] Parsed changes:', changes);
        return { changes, lockedSkipped };
    } catch (err: any) {
        console.error('[DeskFlow] [AI-Categorize] ERROR:', err.message);
        event.sender.send('provider-chunk', { delta: null, done: true, error: err.message, purpose: 'category' });
        return { changes: [], lockedSkipped: [] };
    }
});

function migrateProviderNames(state: any): any {
  if (!state || !state.providers) return state;
  const oldToNew: Record<string, string> = { cloudflayer: 'cloudflare', ollamah: 'ollama', olamah: 'ollama', gemini: 'google', 'google-ai-studio': 'google' };
  const labelFixes: Record<string, string> = { cloudflayer: 'Cloudflare', ollamah: 'Ollama', olamah: 'Ollama', gemini: 'Google Gemini', 'google-ai-studio': 'Google Gemini' };
  state.providers = state.providers.filter((p: any) => {
    const lowId = (p.id || '').toLowerCase();
    const lowTid = (p.templateId || '').toLowerCase();
    return lowId !== 'invilier' && lowTid !== 'invilier';
  });
  for (const p of state.providers) {
    const idFixed = oldToNew[(p.id || '').toLowerCase()];
    const tidFixed = oldToNew[(p.templateId || '').toLowerCase()];
    const fixed = idFixed || tidFixed;
    if (fixed) {
      p.id = fixed;
      p.templateId = fixed;
      p.label = ({ cloudflare: 'Cloudflare', ollama: 'Ollama' })[fixed] || p.label;
      if (PROVIDER_TEMPLATES[fixed]?.defaultBaseUrl && !p.baseUrl?.trim()) p.baseUrl = '';
    }
    const lowLabel = (p.label || '').toLowerCase();
    const labelFixed = labelFixes[lowLabel];
    if (labelFixed) {
      p.label = labelFixed;
    }
  }
  return state;
}

const DEFAULT_PROVIDERS: Array<{ id: string; templateId: string; label: string; enabled: boolean; apiKey: string; baseUrl: string; models: string[]; priority: number }> = [
  { id: 'openrouter', templateId: 'openrouter', label: 'OpenRouter', enabled: true, apiKey: '', baseUrl: '', models: ['google/gemini-2.0-flash-001'], priority: 0 },
  { id: 'google', templateId: 'google', label: 'Google Gemini', enabled: false, apiKey: '', baseUrl: '', models: ['gemini-2.5-flash', 'gemini-2.5-pro', 'gemini-2.0-flash', 'gemini-2.0-flash-lite'], priority: 1 },
  { id: 'cloudflare', templateId: 'cloudflare', label: 'Cloudflare', enabled: false, apiKey: '', baseUrl: '', models: [], priority: 2 },
  { id: 'ollama', templateId: 'ollama', label: 'Ollama', enabled: false, apiKey: '', baseUrl: '', models: ['llama3.1'], priority: 3 },
  { id: 'github', templateId: 'github', label: 'GitHub Models', enabled: false, apiKey: '', baseUrl: '', models: ['gpt-4o-mini', 'gpt-4o', 'DeepSeek-V3', 'Mistral-large', 'Llama-3.1-70B'], priority: 4 },
  { id: 'custom', templateId: 'custom', label: 'Custom OpenAI-compatible', enabled: false, apiKey: '', baseUrl: '', models: [], priority: 5 },
];

function ensureAllTemplateProviders(state: any): any {
  if (!state || !state.providers) return state;

  // Migrate old provider ids: gemini → google, google-ai-studio → google
  for (const p of state.providers) {
    if (p.id === 'gemini' || p.id === 'google-ai-studio') {
      const target = state.providers.find((x: any) => x.id === 'google');
      if (!target) {
        // Rename this provider to google
        p.id = 'google';
        p.templateId = 'google';
        p.label = 'Google Gemini';
      }
      // else: 'google' already exists, this duplicate will be dropped below
    }
  }
  // Remove duplicates (keep first 'google', drop old ids)
  const seen = new Set<string>();
  state.providers = state.providers.filter((p: any) => {
    if (p.id === 'gemini' || p.id === 'google-ai-studio') return false; // already migrated or dropped
    if (seen.has(p.id)) return false;
    seen.add(p.id);
    return true;
  });

  const existingIds = new Set(state.providers.map((p: any) => p.id));
  for (const def of DEFAULT_PROVIDERS) {
    if (!existingIds.has(def.id)) {
      state.providers.push({ ...def, apiKey: def.id === 'openrouter' ? getOpenRouterApiKey() : '' });
      existingIds.add(def.id);
    }
  }
  return state;
}

