electron_1.ipcMain.handle('ai-chat:load', async (_event, threadDate: string) => {
  try {
    const rows = db.prepare('SELECT id, role, content, parsed_json, created_at FROM ai_chat_messages WHERE thread_date = ? ORDER BY id ASC').all(threadDate) as any[];
    return { success: true, messages: rows.map(r => ({ id: r.id, role: r.role, content: r.content, parsed_json: r.parsed_json, timestamp: Date.parse(String(r.created_at).replace(' ', 'T') + 'Z') || Number(r.created_at) || 0 })) };
  } catch (err: any) { return { success: false, error: err.message, messages: [] }; }
});

electron_1.ipcMain.handle('ai-chat:save', async (_event, data: { threadDate: string; messages: Array<{ role: string; content: string; parsed_json?: string; timestamp?: number }> }) => {
  try {
    const { threadDate, messages } = data;

    // Derive thread metadata
    const lastMsg = messages[messages.length - 1];
    const preview = messages.find((m: any) => m.role === "user")?.content?.slice(0, 80) ?? "";
    const now = Date.now();

    const tx = db.transaction(() => {
      // Upsert thread metadata
      db.prepare(`
        INSERT INTO ai_chat_threads (thread_date, message_count, last_message_at, preview, updated_at)
        VALUES (?, ?, ?, ?, ?)
        ON CONFLICT(thread_date) DO UPDATE SET
          message_count = excluded.message_count,
          last_message_at = excluded.last_message_at,
          preview = excluded.preview,
          updated_at = excluded.updated_at
      `).run(threadDate, messages.length, lastMsg?.timestamp ?? now, preview, now);

      // Save messages
      db.prepare('DELETE FROM ai_chat_messages WHERE thread_date = ?').run(threadDate);
      const insert = db.prepare('INSERT INTO ai_chat_messages (thread_date, role, content, parsed_json, created_at) VALUES (?, ?, ?, ?, datetime(?/1000, \'unixepoch\'))');
      for (const msg of messages) {
        insert.run(threadDate, msg.role, msg.content, msg.parsed_json || null, msg.timestamp || Date.now());
      }
    });
    tx();
    // Capture AI chat episode into context brain (debounced per thread)
    try {
      episodeWriters.writeAiChatEpisode(messages.filter((m: any) => m.role === 'user'), threadDate);
    } catch {}
    // Mirror into the Chat Library so in-app chats are searchable/groupable
    // alongside external-AI captures. Idempotent — same transcript is a no-op.
    try {
      chatLib().ingestConversation(db, {
        source: 'deskflow_chat',
        provider: data.providerId || 'deskflow',
        externalId: threadDate,
        messages: messages.map((m: any) => ({
          role: m.role,
          content: m.content,
          timestamp: m.timestamp,
        })),
      });
    } catch (e: any) {
      console.warn('[ai-chat:save] chat library ingest failed:', e?.message);
    }
    return { success: true };
  } catch (err: any) {
    return { success: false, error: err.message };
  }
});

