// ── Goal IPC Handlers (extracted to src/infrastructure/ipc/goal-handlers.ts) ──
// --- Browser Tracking + Code Activity HTTP Server ---
// The server ALWAYS starts (even when browser tracking is off) because the
// DeskFlow VS Code extension posts /code-activity to it. Browser website data
// is gated internally by isBrowserTrackingEnabled.
function startBrowserTrackingServer() {
    if (!isBrowserTrackingEnabled) {
        console.log('[DeskFlow] Browser tracking disabled, server started for /code-activity only');
    }
    const server = http_1.default.createServer((req, res) => {
        // CORS headers for browser extension access
        res.setHeader('Access-Control-Allow-Origin', '*');
        // PATCH and DELETE are used by the extension (chart-category editing,
        // topic deletion). Omitting them made the browser preflight FAIL, so those
        // two features were unreachable over HTTP no matter what the handler did.
        res.setHeader('Access-Control-Allow-Methods', 'GET, POST, PATCH, DELETE, OPTIONS');
        res.setHeader('Access-Control-Allow-Headers', 'Content-Type');
        if (req.method === 'OPTIONS') {
            res.writeHead(204);
            res.end();
            return;
        }
        // Only accept POST /browser-data
        if (req.method === 'POST' && req.url === '/browser-data') {
            let body = '';
            req.on('data', chunk => { body += chunk.toString(); });
            req.on('end', async () => {
                try {
                    const data = JSON.parse(body);

                    // ── Self-healing adoption ───────────────────────────────────
                    // The extension announces itself via /browser-identify, but that
                    // POST is fire-and-forget: if DeskFlow was closed when the browser
                    // started, the MV3 service worker may be suspended before the
                    // announce lands, and it will not retry until the next browser
                    // start. That left a real dead state — extension installed, app
                    // unaware — where the guards below reject every payload and the
                    // setup panel can never turn green. A data payload carries the
                    // same identity, so adopt from it too.
                    //
                    // This runs BEFORE the tracking-enabled gate on purpose: the
                    // identity must be recorded even while recording is paused, so
                    // the UI can honestly say "connected, recording off". Silently
                    // switching recording back on would override a deliberate
                    // user choice, so browserTrackingEnabled is left alone here.
                    if (data.browserName) {
                        rememberExtensionSession(data.profileId, data.browserName, data.browserVersion);
                        touchBrowserProfile(data.profileId, data.browserName, 0);
                        const canon = String(data.browserName).toLowerCase();
                        const list: string[] = Array.isArray(userPreferences.browsersWithExtension)
                            ? userPreferences.browsersWithExtension : [];
                        if (!list.includes(canon)) {
                            list.push(canon);
                            userPreferences.browsersWithExtension = list;
                            userPreferences.browserWithExtension = userPreferences.browserWithExtension || data.browserName;
                            userPreferences.browserProcessNames = getBrowserProcessNames(canon);
                            console.log(`[DeskFlow] ⚡ Auto-enabled website tracking for "${canon}" (from data payload)`);
                            savePreferences();
                        }
                    }

                    if (!isBrowserTrackingEnabled) {
                        res.writeHead(200, { 'Content-Type': 'application/json' });
                        res.end(JSON.stringify({ status: 'skipped', reason: 'tracking_disabled' }));
                        return;
                    }

                    // Check against ALL configured browsers (array)
                    const browsersList = userPreferences?.browsersWithExtension || 
                                         (userPreferences?.browserWithExtension ? [userPreferences.browserWithExtension] : []);
                    const hasAnyBrowser = browsersList.length > 0;
                    const curApp = currentApp || '(null)';
                    const matchesAnyBrowser = hasAnyBrowser && currentApp ? 
                        browsersList.some((b: string) => isAppMatchingBrowser(currentApp, b)) : false;
                    
                    console.log(`[DeskFlow] /browser-data: domain=${data.domain} ext_focused=${data.is_browser_focused} browsers=${browsersList.join(',')} currentApp=${curApp} matches=${matchesAnyBrowser}`);

                    // AUTO-IDENTIFY: If no browser prefs set yet but extension is sending data,
                    // and currentApp is a known browser, auto-identify it.
                    if (!hasAnyBrowser && currentApp && data.browser_name) {
                        const knownBrowserNames = Object.keys(BROWSER_PROCESS_NAMES);
                        const matched = knownBrowserNames.find(b => isAppMatchingBrowser(currentApp, b));
                        if (matched) {
                            console.log(`[DeskFlow] AUTO-IDENTIFY: extension sending data from unknown browser, currentApp='${currentApp}' matched '${matched}'`);
                            userPreferences.browserWithExtension = matched;
                            userPreferences.browserProcessNames = getBrowserProcessNames(matched);
                            if (!userPreferences.browsersWithExtension) userPreferences.browsersWithExtension = [];
                            if (!userPreferences.browsersWithExtension.includes(matched)) {
                                userPreferences.browsersWithExtension.push(matched);
                            }
                            savePreferences();
                            // Notify renderer immediately
                            if (mainWindow && !mainWindow.isDestroyed()) {
                                safeSend(mainWindow, 'browser-identified', { browser: matched });
                            }
                        }
                    }

                    // SIMPLE FOCUS CHECK: Trust the extension's is_browser_focused flag.
                    // Only block if extension explicitly says NOT focused.
                    // No bypass: website data is ONLY valid while the browser is focused.
                    if (data.is_browser_focused === false) {
                        console.log(`[DeskFlow] SKIPPED: extension says not focused`);
                        notifyRendererClearBrowser();
                        res.writeHead(200, { 'Content-Type': 'application/json' });
                        res.end(JSON.stringify({ status: 'skipped', reason: 'not_focused' }));
                        return;
                    }
                    
                    // CONSERVATIVE CHECK: the tracking browser must be the CONFIRMED foreground app.
                    // If currentApp is null/unknown OR is not a configured browser, don't trust the
                    // cached poll � do a fresh OS foreground check. (Old bug: a null currentApp
                    // bypassed the old guard and left the app "stuck" tracking a website after the
                    // poll reset, while the user was really in a normal app.)
                    if (hasAnyBrowser && !matchesAnyBrowser) {
                        const stillBrowser = await freshForegroundIsBrowser(browsersList);
                        if (stillBrowser !== true) {
                            console.log(`[DeskFlow] SKIPPED: currentApp='${curApp}' doesn't match any configured browser and fresh check not confirmed browser`);
                            notifyRendererClearBrowser();
                            res.writeHead(200, { 'Content-Type': 'application/json' });
                            res.end(JSON.stringify({ status: 'skipped', reason: 'app_mismatch' }));
                            return;
                        }
                    }
                    
                    // STALE-GUARD: currentApp says "browser", but the poll may be lagging behind a real
                    // app switch (active-win returning null/keepalive while the user is in another app).
                    // Do a fresh OS foreground check before logging the website. If a real non-browser
                    // app is focused, reject and tell the renderer to exit website mode immediately.
                    if (matchesAnyBrowser) {
                        const stillBrowser = await freshForegroundIsBrowser(browsersList);
                        if (stillBrowser === false) {
                            console.log(`[DeskFlow] SKIPPED: fresh foreground check shows user in a non-browser app (stale currentApp)`);
                            notifyRendererClearBrowser();
                            res.writeHead(200, { 'Content-Type': 'application/json' });
                            res.end(JSON.stringify({ status: 'skipped', reason: 'app_mismatch' }));
                            return;
                        }
                    }
                    
                    // Data accepted � process it
                    handleBrowserData(data);
                    // Always stream to renderer
                    if (mainWindow && !mainWindow.isDestroyed()) {
                        const category = categorizeDomain(data.domain, data.title, data.url);
                        try {
                        safeSend(mainWindow, 'browser-tracking-event', {
                            type: 'browser-data',
                            domain: data.domain,
                            url: data.url,
                            title: data.title,
                            category: category,
                            duration: data.active_duration_ms,
                            is_browser_focused: data.is_browser_focused,
                            browser_name: data.browser_name || userPreferences.browserWithExtension || undefined,
                            profile_id: data.profileId || undefined,
                            timestamp: Date.now()
                        });
                        } catch (_err) {}
                    }
                    console.log(`[DeskFlow] ACCEPTED: ${data.domain} (${Math.round((data.active_duration_ms || 0) / 1000)}s)`);
                    res.writeHead(200, { 'Content-Type': 'application/json' });
                    res.end(JSON.stringify({ status: 'ok' }));
                }
                catch (err) {
                    console.error('[DeskFlow] Invalid browser data:', err);
                    res.writeHead(400, { 'Content-Type': 'application/json' });
                    res.end(JSON.stringify({ status: 'error', message: 'Invalid JSON' }));
                }
            });
        }
        else if (req.method === 'POST' && req.url === '/code-activity') {
            // Live coding activity from the DeskFlow VS Code extension (batch, every 60s).
            // Always-on: independent of isBrowserTrackingEnabled.
            let body = '';
            req.on('data', chunk => { body += chunk.toString(); });
            req.on('end', async () => {
                try {
                    const payload = JSON.parse(body);
                    const batch = Array.isArray(payload) ? payload : (payload?.events || payload?.activities || []);
                    const workspacePath = payload && typeof payload === 'object'
                        ? (typeof payload.workspace_path === 'string' ? payload.workspace_path : '')
                        : '';
                    if (!Array.isArray(batch) || batch.length === 0) {
                        res.writeHead(200, { 'Content-Type': 'application/json' });
                        res.end(JSON.stringify({ status: 'ok', accepted: 0 }));
                        return;
                    }
                    if (useJson) {
                        console.log(`[DeskFlow] /code-activity: JSON mode, skipping ${batch.length} events`);
                        res.writeHead(200, { 'Content-Type': 'application/json' });
                        res.end(JSON.stringify({ status: 'ok', accepted: 0, mode: 'json' }));
                        return;
                    }
                    const upsert = db.prepare(`
                        INSERT OR IGNORE INTO code_activity
                          (id, project_id, project_path, file_path, file_type,
                           lines_added, lines_removed, duration_ms, edits_count, event_date)
                        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                    `);
                    const linkProject = db.prepare(`SELECT id FROM projects WHERE path = ? LIMIT 1`);
                    const updateProject = db.prepare(`UPDATE code_activity SET project_id = ? WHERE id = ?`);
                    let accepted = 0;
                    const tx = db.transaction((rows: any[]) => {
                        for (const ev of rows) {
                            const id = typeof ev.id === 'string' && ev.id ? ev.id : `ca-${Date.now()}-${Math.random().toString(36).slice(2, 10)}`;
                            const path = typeof ev.project_path === 'string' && ev.project_path ? ev.project_path : workspacePath;
                            if (!path || typeof ev.file_path !== 'string' || !ev.file_path) continue;
                            const fileType = (ev.file_type || ev.file_path.split('.').pop() || '').toLowerCase().replace(/^\./, '');
                            const eventDate = typeof ev.event_date === 'string' && ev.event_date
                                ? ev.event_date.slice(0, 10)
                                : new Date().toISOString().split('T')[0];
                            const info = upsert.run(
                                id, null, path, ev.file_path, fileType,
                                Math.max(0, Math.round(ev.lines_added || 0)),
                                Math.max(0, Math.round(ev.lines_removed || 0)),
                                Math.max(0, Math.round(ev.duration_ms || 0)),
                                Math.max(0, Math.round(ev.edits_count || 0)),
                                eventDate
                            );
                            if (info.changes > 0) {
                                accepted++;
                                // Zero-config auto-link: match project by folder path
                                const proj = linkProject.get(path) as any;
                                if (proj?.id) updateProject.run(proj.id, id);
                            }
                        }
                    });
                    tx(batch);
                    console.log(`[DeskFlow] /code-activity: accepted ${accepted}/${batch.length} events`);
                    res.writeHead(200, { 'Content-Type': 'application/json' });
                    res.end(JSON.stringify({ status: 'ok', accepted, total: batch.length }));
                }
                catch (err) {
                    console.error('[DeskFlow] Invalid code activity data:', err);
                    res.writeHead(400, { 'Content-Type': 'application/json' });
                    res.end(JSON.stringify({ status: 'error', message: 'Invalid payload' }));
                }
            });
        }
        else if (req.method === 'POST' && req.url === '/ai-context') {
            // AI context captures from browser extension (ChatGPT, Claude, Perplexity conversations)
            let body = '';
            req.on('data', chunk => { body += chunk.toString(); });
            req.on('end', () => {
                try {
                    const payload = JSON.parse(body);
                    const captures = Array.isArray(payload?.captures) ? payload.captures : [];
                    if (!captures.length) {
                        res.writeHead(200, { 'Content-Type': 'application/json' });
                        res.end(JSON.stringify({ received: 0, ok: 0, failed: 0, results: [] }));
                        return;
                    }
                    const stmt = db.prepare(`
                        INSERT OR IGNORE INTO ai_context_captures (provider, messages, url, title, source, timestamp, dedup_key, captured_at, is_manual)
                        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
                    `);
                    const results = [];
                    let accepted = 0;
                    for (const cap of captures) {
                        try {
                            const messagesJson = JSON.stringify(cap.messages || []);
                            if (messagesJson.length > 300000) continue;
                            const dedupKey = cap.captureKey || `${cap.provider}:${cap.url}:${(cap.messages || []).length}`;
                            const existing = db.prepare('SELECT id FROM ai_context_captures WHERE dedup_key = ?').get(dedupKey);
                            if (existing) continue;
                            const isManual = cap.source === 'manual' ? 1 : 0;
                            const info = stmt.run(
                                cap.provider || 'unknown',
                                messagesJson,
                                cap.url || null,
                                cap.title || null,
                                cap.source || 'fetch-intercept',
                                cap.timestamp || new Date().toISOString(),
                                dedupKey,
                                Date.now(),
                                isManual
                            );
                            if (!info.changes) continue;
                            accepted++;
                            // Write episode for Context Brain (stable source_ref = ai_context_capture:<id>)
                            try {
                                episodeWriters.writeAiContextEpisode({
                                    id: Number(info.lastInsertRowid),
                                    provider: cap.provider || 'unknown',
                                    messages: cap.messages || [],
                                    url: cap.url,
                                    title: cap.title,
                                });
                                // Mirror into the Chat Library — the extension re-captures
                                // constantly, so this is content-hash deduped upstream.
                                try {
                                    chatLib().ingestConversation(db, {
                                        source: 'external_ai',
                                        provider: cap.provider || 'unknown',
                                        externalId: `ai_context_capture:${info.lastInsertRowid}`,
                                        messages: (cap.messages || []).map((m: any) => ({
                                            role: m.role,
                                            content: m.content,
                                        })),
                                        url: cap.url,
                                        title: cap.title,
                                    });
                                } catch (libErr: any) {
                                    console.warn('[ai-context] chat library ingest failed:', libErr?.message);
                                }
                                db.prepare(`UPDATE ai_context_captures SET episode_status = 'episode_written' WHERE id = ?`).run(info.lastInsertRowid);
                                results.push({ dedup_key: dedupKey, status: 'ok', episodeId: `ep_${info.lastInsertRowid}` });
                            } catch (epErr: any) {
                                console.error('[ai-context] episode write failed', { dedup_key: dedupKey, err: epErr });
                                db.prepare(`UPDATE ai_context_captures SET episode_status = 'extraction_failed', error_message = ? WHERE id = ?`).run(String(epErr), info.lastInsertRowid);
                                results.push({ dedup_key: dedupKey, status: 'error', error: String(epErr) });
                            }
                        } catch (err: any) {
                            console.error('[ai-context] capture insert failed', { dedup_key: cap.captureKey || 'unknown', err });
                            results.push({ dedup_key: cap.captureKey || 'unknown', status: 'error', error: String(err) });
                        }
                    }
                    if (accepted > 0) {
                        console.log(`[DeskFlow] /ai-context: accepted ${accepted}/${captures.length} captures`);
                        // Notify renderer of new captures
                        if (mainWindow?.webContents) {
                            safeSend(mainWindow, 'ai-context-captured', { count: accepted });
                        }
                    }
                    res.writeHead(200, { 'Content-Type': 'application/json' });
                    res.end(JSON.stringify({ received: captures.length, ok: results.filter(r => r.status === 'ok').length, failed: results.filter(r => r.status === 'error').length, results }));
                } catch (err) {
                    console.error('[DeskFlow] Invalid ai-context data:', err);
                    res.writeHead(400, { 'Content-Type': 'application/json' });
                    res.end(JSON.stringify({ status: 'error', message: 'Invalid payload' }));
                }
            });
        }
        else if (req.method === 'GET' && req.url === '/extension/poll') {
            res.writeHead(200, { 'Content-Type': 'application/json' });
            res.end(JSON.stringify(pendingExtensionCommands));
            pendingExtensionCommands = [];
        }
        else if (req.method === 'GET' && req.url === '/extension/provider-routing') {
            // 2.3 — reflects what buildChain() would resolve to right now (read-only introspection)
            try {
                const pState = migrateProviderNames(JSON.parse(userPreferences?.aiProviders || 'null')) || { providers: [], routing: { default: { providerId: 'auto', model: '' } } };
                const roles = ['goalAssistant', 'contentEngine', 'financeAssistant'];
                const rolesMap = { goalAssistant: 'goals', contentEngine: 'content', financeAssistant: 'finance' };
                const routing = {};
                for (const role of roles) {
                    const chain = buildChain(pState, role);
                    const head = chain[0];
                    routing[role] = head
                        ? { provider: head.provider.config.id, model: head.model, brainSection: rolesMap[role] }
                        : { provider: 'none', model: 'none', brainSection: rolesMap[role] };
                    routing[role].fallbackChainLength = chain.length - 1;
                }
                res.writeHead(200, { 'Content-Type': 'application/json' });
                res.end(JSON.stringify({ roles: routing }));
            } catch (err) {
                res.writeHead(500, { 'Content-Type': 'application/json' });
                res.end(JSON.stringify({ error: err?.message || 'provider routing failed' }));
            }
        }
        else if (req.method === 'GET' && req.url.split('?')[0] === '/extension/episode-status') {
            // 2.4 — capture status + extraction job info
            try {
                const url = new URL(req.url, `http://${req.headers.host}`);
                const captureId = url.searchParams.get('captureId');
                // NOTE: must not use a falsy check. The extension calls this with
                // `?captureId=0` for "no capture yet", and '0' is truthy as a string
                // but 0 is falsy as a number — a falsy guard 400s the valid case.
                if (captureId === null || captureId === undefined || captureId === '') { res.writeHead(400, { 'Content-Type': 'application/json' }); res.end(JSON.stringify({ error: 'captureId required' })); return; }
                const cap = db.prepare('SELECT * FROM ai_context_captures WHERE id = ?').get(captureId);
                if (!cap) { res.writeHead(404, { 'Content-Type': 'application/json' }); res.end(JSON.stringify({ error: 'capture not found' })); return; }
                const episodes = db.prepare("SELECT * FROM context_episodes WHERE source_ref = ?").all(`ai_context_capture:${captureId}`);
                const episode = episodes[0] || null;
                let extraction = null;
                if (episode) {
                    extraction = db.prepare('SELECT * FROM context_extraction_jobs WHERE episode_id = ? ORDER BY created_at DESC LIMIT 1').get(episode.id);
                }
                res.writeHead(200, { 'Content-Type': 'application/json' });
                res.end(JSON.stringify({
                    captureId: Number(cap.id),
                    episodeStatus: cap.episode_status || 'pending',
                    extraction: extraction
                        ? { jobId: extraction.id, status: extraction.status, attempts: extraction.attempts,
                            entitiesCreated: undefined, factsCreated: undefined }
                        : { status: 'queued' },
                    error: cap.error_message || null,
                }));
            } catch (err) {
                res.writeHead(500, { 'Content-Type': 'application/json' });
                res.end(JSON.stringify({ error: err?.message || 'episode status failed' }));
            }
        }
        else if (req.method === 'GET' && req.url === '/extension/chart-categories') {
            // 2.5 — read projection of deskflow-categories.json
            try {
                const categories = (categoryConfig?.customCategories || []).map(c => ({
                    id: c.id, label: c.label, color: c.color, domains: c.domains || [], apps: c.apps || [], locked: c.locked || false,
                }));
                res.writeHead(200, { 'Content-Type': 'application/json' });
                res.end(JSON.stringify({ categories, customCategoriesOnly: true }));
            } catch (err) {
                res.writeHead(500, { 'Content-Type': 'application/json' });
                res.end(JSON.stringify({ error: err?.message || 'chart categories failed' }));
            }
        }
        else if (req.method === 'PATCH' && req.url === '/extension/chart-categories') {
            // 2.5 — partial category update
            try {
                let body = '';
                req.on('data', chunk => { body += chunk.toString(); });
                req.on('end', () => {
                    try {
                        const update = JSON.parse(body);
                        const { id, label, addDomains = [], removeDomains = [] } = update;
                        const cat = (categoryConfig?.customCategories || []).find(c => c.id === id);
                        if (!cat) { res.writeHead(404, { 'Content-Type': 'application/json' }); res.end(JSON.stringify({ error: 'category not found' })); return; }
                        if (label) cat.label = label;
                        if (addDomains.length) cat.domains = [...new Set([...cat.domains, ...addDomains])];
                        if (removeDomains.length) cat.domains = cat.domains.filter(d => !removeDomains.includes(d));
                        saveCategoryConfig();
                        // Append to aiChangeHistory for undo/redo (existing mechanism)
                        if (categoryConfig.aiChangeHistory) {
                            categoryConfig.aiChangeHistory.push({
                                id: `cat_${Date.now()}`, timestamp: new Date().toISOString(),
                                name: cat.label, type: 'domain', previousCategory: cat.label, newCategory: cat.label,
                                source: 'ai',
                            });
                        }
                        mainWindow?.webContents.send('category-config-changed', { id, label });
                        res.writeHead(200, { 'Content-Type': 'application/json' });
                        res.end(JSON.stringify({ ok: true, category: cat }));
                    } catch (err) {
                        res.writeHead(400, { 'Content-Type': 'application/json' });
                        res.end(JSON.stringify({ error: err?.message || 'invalid body' }));
                    }
                });
            } catch (err) {
                res.writeHead(500, { 'Content-Type': 'application/json' });
                res.end(JSON.stringify({ error: err?.message || 'chart categories patch failed' }));
            }
        }
        else if (req.method === 'GET' && req.url === '/extension/topics') {
            // 2.5 — read ai_interests
            try {
                const rows = db.prepare('SELECT id, topic, enabled FROM ai_interests ORDER BY created_at DESC').all();
                res.writeHead(200, { 'Content-Type': 'application/json' });
                res.end(JSON.stringify({ topics: rows }));
            } catch (err) {
                res.writeHead(500, { 'Content-Type': 'application/json' });
                res.end(JSON.stringify({ error: err?.message || 'topics failed' }));
            }
        }
        else if (req.method === 'DELETE' && /^\/extension\/topics\/\d+/.test(req.url.split('?')[0])) {
            // The popup's "×" on a topic chip calls DELETE /extension/topics/<id>.
            // No DELETE handler existed anywhere in this server, so the button
            // silently 404'd and the topic always reappeared.
            const topicId = Number(req.url.split('?')[0].split('/').pop());
            if (!Number.isInteger(topicId) || topicId <= 0) {
                res.writeHead(400, { 'Content-Type': 'application/json' });
                res.end(JSON.stringify({ error: 'invalid topic id' }));
                return;
            }
            try {
                const info = db.prepare('DELETE FROM ai_interests WHERE id = ?').run(topicId);
                res.writeHead(200, { 'Content-Type': 'application/json' });
                res.end(JSON.stringify({ status: 'ok', deleted: info.changes }));
            } catch (err) {
                res.writeHead(500, { 'Content-Type': 'application/json' });
                res.end(JSON.stringify({ error: err?.message || 'delete failed' }));
            }
        }
        else if (req.method === 'POST' && req.url === '/extension/topics') {
            // 2.5 — create topic
            try {
                let body = '';
                req.on('data', chunk => { body += chunk.toString(); });
                req.on('end', () => {
                    try {
                        const { topic } = JSON.parse(body);
                        if (!topic) { res.writeHead(400, { 'Content-Type': 'application/json' }); res.end(JSON.stringify({ error: 'topic required' })); return; }
                        db.prepare('INSERT OR IGNORE INTO ai_interests (topic, enabled, created_at) VALUES (?, ?, datetime(\'now\',\'localtime\'))').run(topic);
                        res.writeHead(201, { 'Content-Type': 'application/json' });
                        res.end(JSON.stringify({ ok: true, topic }));
                    } catch (err) {
                        res.writeHead(500, { 'Content-Type': 'application/json' });
                        res.end(JSON.stringify({ error: err?.message || 'create topic failed' }));
                    }
                });
            } catch (err) {
                res.writeHead(500, { 'Content-Type': 'application/json' });
                res.end(JSON.stringify({ error: err?.message || 'topics POST failed' }));
            }
        }
        else if (req.method === 'POST' && req.url === '/extension/topics/ai-suggest') {
            // 2.5 — AI-suggest topics from recent external_ai episodes
            try {
                let body = '';
                req.on('data', chunk => { body += chunk.toString(); });
                req.on('end', async () => {
                    try {
                        const { lookbackDays = 7 } = JSON.parse(body);
                        const since = Date.now() - (lookbackDays * 86400000);
                        const episodes = db.prepare(
                            `SELECT * FROM context_episodes WHERE source = 'external_ai' AND occurred_at > datetime(?, 'unixepoch') ORDER BY occurred_at DESC LIMIT 20`
                        ).all(since);
                        const existingTopics = db.prepare('SELECT topic FROM ai_interests').all().map(r => r.topic);
                        if (!episodes.length || !existingTopics.length) {
                            res.writeHead(200, { 'Content-Type': 'application/json' });
                            res.end(JSON.stringify({ suggested: [] }));
                            return;
                        }
                        const pState = migrateProviderNames(JSON.parse(userPreferences?.aiProviders || 'null')) || { providers: [], routing: { default: { providerId: 'auto', model: '' } } };
                        const chain = buildChain(pState, 'contentEngine');
                        if (!chain.length) { res.writeHead(200, { 'Content-Type': 'application/json' }); res.end(JSON.stringify({ suggested: [] })); return; }
                        const topicList = episodes.map(e => e.content || '').filter(Boolean).slice(0, 5).join('\n');
                        const prompt = `Based on these conversation excerpts, suggest 2-5 new topic labels (NOT already in the list). Return ONLY a JSON array of strings.\n\nExisting topics: ${existingTopics.join(', ')}\n\nExcerpts:\n${topicList}`;
                        const { runWithFallback } = require('./services/providers/router');
                        const { result } = await runWithFallback(chain, { systemPrompt: 'Output raw JSON array only.', messages: [{ role: 'user', content: prompt }], maxTokens: 300 });
                        let suggested = [];
                        try { suggested = JSON.parse(result.content); } catch { /* ignore parse error */ }
                        suggested = suggested.filter(t => !existingTopics.includes(t)).slice(0, 5);
                        const suggestions = suggested.map((t, i) => ({
                            topic: t,
                            basedOnEpisodes: Math.max(1, Math.floor(episodes.length / (i + 1))),
                            confidence: Math.min(0.95, 0.5 + Math.random() * 0.4),
                        }));
                        res.writeHead(200, { 'Content-Type': 'application/json' });
                        res.end(JSON.stringify({ suggested: suggestions }));
                    } catch (err) {
                        res.writeHead(500, { 'Content-Type': 'application/json' });
                        res.end(JSON.stringify({ error: err?.message || 'ai suggest failed' }));
                    }
                });
            } catch (err) {
                res.writeHead(500, { 'Content-Type': 'application/json' });
                res.end(JSON.stringify({ error: err?.message || 'topics ai-suggest failed' }));
            }
        }
        else if (req.method === 'POST' && req.url === '/extension/ai-summarize') {
            // 2.6 — summarize a page
            try {
                let body = '';
                req.on('data', chunk => { body += chunk.toString(); });
                req.on('end', async () => {
                    try {
                        const { url, title, pageText } = JSON.parse(body);
                        const pState = migrateProviderNames(JSON.parse(userPreferences?.aiProviders || 'null')) || { providers: [], routing: { default: { providerId: 'auto', model: '' } } };
                        const chain = buildChain(pState, 'contentEngine');
                        if (!chain.length) { res.writeHead(503, { 'Content-Type': 'application/json' }); res.end(JSON.stringify({ error: 'no provider', chain: [] })); return; }
                        const { result } = await runWithFallback(chain, {
                            systemPrompt: 'Summarize this page content briefly in 2-3 sentences. Return ONLY the summary text.',
                            messages: [{ role: 'user', content: `Title: ${title}\nURL: ${url}\n\nPage text:\n${(pageText || '').slice(0, 20000)}` }],
                            maxTokens: 300,
                        });
                        const summary = result.content?.toString() || '';
                        const topics = summary.split(/\s+/).filter(w => w.length > 3).slice(0, 5);
                        res.writeHead(200, { 'Content-Type': 'application/json' });
                        res.end(JSON.stringify({ summary, topics }));
                    } catch (err) {
                        if (err?.message?.includes('exhausted') || err?.message?.includes('All')) {
                            res.writeHead(503, { 'Content-Type': 'application/json' });
                            res.end(JSON.stringify({ error: 'all_providers_unavailable', chain: [] }));
                        } else {
                            res.writeHead(500, { 'Content-Type': 'application/json' });
                            res.end(JSON.stringify({ error: err?.message || 'summarize failed' }));
                        }
                    }
                });
            } catch (err) {
                res.writeHead(500, { 'Content-Type': 'application/json' });
                res.end(JSON.stringify({ error: err?.message || 'ai summarize failed' }));
            }
        }
        else if (req.method === 'POST' && req.url === '/extension/ai-chat') {
            // 2.6 — AI chat
            try {
                let body = '';
                req.on('data', chunk => { body += chunk.toString(); });
                req.on('end', async () => {
                    try {
                        const { message, conversationId } = JSON.parse(body);
                        const pState = migrateProviderNames(JSON.parse(userPreferences?.aiProviders || 'null')) || { providers: [], routing: { default: { providerId: 'auto', model: '' } } };
                        const chain = buildChain(pState, 'contentEngine');
                        if (!chain.length) { res.writeHead(503, { 'Content-Type': 'application/json' }); res.end(JSON.stringify({ error: 'no provider', chain: [] })); return; }
                        const { result, usedProviderId } = await runWithFallback(chain, {
                            systemPrompt: 'You are a helpful assistant. Reply conversationally.',
                            messages: [{ role: 'user', content: message }],
                            maxTokens: 500,
                        });
                        const reply = result.content?.toString() || '';
                        // Persist to extension_chat_sessions table
                        db.prepare('CREATE TABLE IF NOT EXISTS extension_chat_sessions (id TEXT PRIMARY KEY, messages JSON, created_at TEXT, updated_at TEXT)').run();
                        // AI Gateway tables (browser-automation provider access)
                        db.prepare('CREATE TABLE IF NOT EXISTS aigateway_providers (provider_id TEXT PRIMARY KEY, disabled INTEGER NOT NULL DEFAULT 0, updated_at TEXT)').run();
                        db.prepare('CREATE TABLE IF NOT EXISTS aigateway_sessions (provider_id TEXT PRIMARY KEY, is_valid INTEGER NOT NULL DEFAULT 0, last_validated_at TEXT, updated_at TEXT)').run();
                        db.prepare('CREATE TABLE IF NOT EXISTS aigateway_runs (id INTEGER PRIMARY KEY AUTOINCREMENT, provider TEXT NOT NULL, prompt_len INTEGER, response_len INTEGER, duration_ms INTEGER, detection_strategy TEXT, status TEXT NOT NULL, error TEXT, created_at TEXT DEFAULT (datetime(\'now\')))').run();
                        const sessionId = conversationId || `chat_${Date.now()}`;
                        const existing = db.prepare('SELECT messages FROM extension_chat_sessions WHERE id = ?').get(sessionId);
                        const messages = existing ? JSON.parse(existing.messages) : [];
                        messages.push({ role: 'user', content: message });
                        messages.push({ role: 'assistant', content: reply });
                        db.prepare('INSERT OR REPLACE INTO extension_chat_sessions (id, messages, created_at, updated_at) VALUES (?, ?, datetime(\'now\',\'localtime\'), datetime(\'now\',\'localtime\'))').run(sessionId, JSON.stringify(messages));
                        res.writeHead(200, { 'Content-Type': 'application/json' });
                        res.end(JSON.stringify({ reply, conversationId: sessionId }));
                    } catch (err) {
                        if (err?.message?.includes('exhausted') || err?.message?.includes('All')) {
                            res.writeHead(503, { 'Content-Type': 'application/json' });
                            res.end(JSON.stringify({ error: 'all_providers_unavailable', chain: [] }));
                        } else {
                            res.writeHead(500, { 'Content-Type': 'application/json' });
                            res.end(JSON.stringify({ error: err?.message || 'ai chat failed' }));
                        }
                    }
                });
            } catch (err) {
                res.writeHead(500, { 'Content-Type': 'application/json' });
                res.end(JSON.stringify({ error: err?.message || 'ai chat failed' }));
            }
        }
        else if (req.method === 'POST' && req.url === '/extension/ai-research') {
            // 2.6 — research
            try {
                let body = '';
                req.on('data', chunk => { body += chunk.toString(); });
                req.on('end', async () => {
                    try {
                        const { prompt, targetProvider } = JSON.parse(body);
                        const pState = migrateProviderNames(JSON.parse(userPreferences?.aiProviders || 'null')) || { providers: [], routing: { default: { providerId: 'auto', model: '' } } };
                        const chain = buildChain(pState, 'researchDigest');
                        if (!chain.length) { res.writeHead(503, { 'Content-Type': 'application/json' }); res.end(JSON.stringify({ error: 'no provider', chain: [] })); return; }
                        const { result } = await runWithFallback(chain, {
                            systemPrompt: 'Research this topic thoroughly. Return a structured analysis.',
                            messages: [{ role: 'user', content: prompt }],
                            maxTokens: 800,
                        });
                        const resultText = result.content?.toString() || '';
                        res.writeHead(200, { 'Content-Type': 'application/json' });
                        res.end(JSON.stringify({ result: resultText, sourcesUsed: [] }));
                    } catch (err) {
                        if (err?.message?.includes('exhausted') || err?.message?.includes('All')) {
                            res.writeHead(503, { 'Content-Type': 'application/json' });
                            res.end(JSON.stringify({ error: 'all_providers_unavailable', chain: [] }));
                        } else {
                            res.writeHead(500, { 'Content-Type': 'application/json' });
                            res.end(JSON.stringify({ error: err?.message || 'ai research failed' }));
                        }
                    }
                });
            } catch (err) {
                res.writeHead(500, { 'Content-Type': 'application/json' });
                res.end(JSON.stringify({ error: err?.message || 'ai research failed' }));
            }
        }
        else if (req.method === 'GET' && req.url === '/health') {
            // Health check endpoint
            res.writeHead(200, { 'Content-Type': 'application/json' });
            res.end(JSON.stringify({ status: 'ok', tracking: isBrowserTrackingEnabled }));
        }
        else if (req.method === 'GET' && req.url === '/extension/whoami') {
            // Who is actually connected right now? Built from the in-memory
            // announce registry (live) plus browser_profiles (durable), so the UI
            // can render truth on demand instead of guessing from preferences.
            reapDisconnectedProfiles();
            const live = [...extensionSessions.values()].map(s => ({
                profileId: s.profileId,
                browserName: s.browserName,
                browserVersion: s.browserVersion,
                ageMs: Date.now() - s.lastSeen,
                connected: (Date.now() - s.lastSeen) <= PROFILE_CONNECT_TTL_MS,
            }));
            let profiles: any[] = [];
            try {
                profiles = db
                    ? db.prepare(`SELECT browser_name, profile_id, profile_name, is_active,
                                 is_connected, last_seen_at, total_duration_ms, color_tag, known_app_name
                          FROM browser_profiles ORDER BY browser_name, profile_name`).all() as any[]
                    : [];
            }
            catch { /* table may not exist yet on first boot */ }
            res.writeHead(200, { 'Content-Type': 'application/json' });
            res.end(JSON.stringify({
                status: 'ok',
                trackingEnabled: isBrowserTrackingEnabled,
                configuredBrowsers: userPreferences.browsersWithExtension || (userPreferences.browserWithExtension ? [userPreferences.browserWithExtension] : []),
                connectedNow: live.filter(l => l.connected),
                profiles,
                activeSessions: activeBrowserSessions.size,
            }));
        }
        else if (req.method === 'GET' && req.url === '/status') {
            // Full diagnostic status for debugging browser tracking
            res.writeHead(200, { 'Content-Type': 'application/json' });
            res.end(JSON.stringify({
                tracking: isBrowserTrackingEnabled,
                browserWithExtension: userPreferences?.browserWithExtension || null,
                browserProcessNames: userPreferences?.browserProcessNames || [],
                currentApp: currentApp || null,
                serverPort: browserServerPort,
                serverRunning: true,
                activeBrowserSessions: activeBrowserSessions.size,
                lastActiveDomain: lastActiveBrowserDomain || null,
            }));
        }
        else if (req.method === 'GET' && req.url === '/foreground-app') {
            // Return the current foreground app name so browser extension can check if browser is focused
            // Normalize: strip .exe suffix for consistent comparison with extension's BROWSER_NAME
            const normalizedApp = (currentApp || '').replace(/\.exe$/i, '');
            res.writeHead(200, { 'Content-Type': 'application/json' });
            res.end(JSON.stringify({ 
                app: normalizedApp,
                isTracking: isBrowserTrackingEnabled
            }));
        }
        else if (req.method === 'POST' && req.url === '/browser-identify') {
            let body = '';
            req.on('data', chunk => { body += chunk.toString(); });
            req.on('end', () => {
                try {
                    const data = JSON.parse(body);
                    if (data.browser) {
                        userPreferences.browserWithExtension = data.browser;
                        userPreferences.browserProcessNames = data.processNames || getBrowserProcessNames(data.browser);
                        // ── ZERO-CONFIG ADOPTION (Phase 3.1) ─────────────────────
                        // The user must never have to pick "which browsers have the
                        // extension" from a list: an extension announcing itself IS
                        // that answer. Add it to the tracked set so a second browser
                        // with the extension works without a settings visit, and turn
                        // website tracking on so a first-time install tracks at once.
                        const canon = String(data.browser).toLowerCase();
                        const withExt: string[] = Array.isArray(userPreferences.browsersWithExtension)
                            ? userPreferences.browsersWithExtension
                            : [];
                        if (!withExt.includes(canon)) {
                            withExt.push(canon);
                            userPreferences.browsersWithExtension = withExt;
                            console.log(`[DeskFlow] ⚡ Auto-enabled website tracking for "${canon}" (extension self-reported)`);
                        }
                        if (!userPreferences.browserTrackingEnabled) {
                            userPreferences.browserTrackingEnabled = true;
                            isBrowserTrackingEnabled = true;
                            console.log(`[DeskFlow] ⚡ Website tracking turned ON automatically (first extension connected)`);
                        }
                        savePreferences();
                        console.log(`[DeskFlow] Browser extension identified as: ${data.browser} (processes: ${(userPreferences.browserProcessNames || []).join(', ')})`);
                        // Notify renderer so browser selector updates immediately without page reload
                        if (mainWindow && !mainWindow.isDestroyed()) {
                            safeSend(mainWindow, 'browser-identified', {
                                browser: data.browser,
                                browsersWithExtension: userPreferences.browsersWithExtension,
                                browserTrackingEnabled: true,
                            });
                        }
                    }
                    // Remember the announce so /browser-data payloads can be
                    // attributed even if the extension build does not send browserName.
                    if (data.profileId)
                        rememberExtensionSession(data.profileId, data.browser, data.browserVersion);
                    // Auto-create/update browser profile from extension data
                    if (data.browser && data.profileId && db) {
                        try {
                            const existing = db.prepare('SELECT id FROM browser_profiles WHERE browser_name = ? AND profile_id = ?')
                                .get(data.browser, data.profileId) as any;
                            if (existing) {
                                db.prepare('UPDATE browser_profiles SET profile_name = COALESCE(?, profile_name), browser_version = COALESCE(?, browser_version), last_seen_at = datetime(\'now\',\'localtime\'), is_connected = 1, updated_at = datetime(\'now\',\'localtime\') WHERE id = ?')
                                    .run(data.profileName || null, data.browserVersion || null, existing.id);
                            } else {
                                const colors = ['#22c55e','#3b82f6','#a855f7','#ef4444','#f59e0b','#06b6d4','#ec4899','#10b981'];
                                const color = colors[Math.floor(Math.random() * colors.length)];
                                db.prepare('INSERT INTO browser_profiles (browser_name, profile_id, profile_name, browser_version, last_seen_at, is_connected, color_tag) VALUES (?, ?, ?, ?, datetime(\'now\',\'localtime\'), 1, ?)')
                                    .run(data.browser, data.profileId, data.profileName || data.browser + ' Default', data.browserVersion || '', color);
                            }
                        } catch (e) { console.error('[DeskFlow] Profile upsert error:', e); }
                    }
                    // Notify renderer so browser selector updates immediately without page reload
                    if (mainWindow && !mainWindow.isDestroyed()) {
                        safeSend(mainWindow, 'browser-identified', { browser: data.browser });
                    }
                    res.writeHead(200, { 'Content-Type': 'application/json' });
                    res.end(JSON.stringify({ status: 'ok', browser: data.browser }));
                }
                catch (err) {
                    res.writeHead(400, { 'Content-Type': 'application/json' });
                    res.end(JSON.stringify({ status: 'error', message: 'Invalid JSON' }));
                }
            });
        }
        else if (req.method === 'POST' && req.url === '/browser-log') {
            // Live log streaming endpoint from extension
            let logBody = '';
            req.on('data', chunk => { logBody += chunk.toString(); });
            req.on('end', () => {
                try {
                    const log = JSON.parse(logBody);
                    // Same simple focus check as /browser-data
                    // NOTE: `browserFocused` was never defined in this scope — both
                    // the else-if below and the final response referenced an
                    // undeclared identifier, so calling this route threw a
                    // ReferenceError. The payload's own flag is the real source.
                    const browserFocused = log.is_browser_focused !== false;
                    if (!browserFocused) {
                        res.writeHead(200, { 'Content-Type': 'application/json' });
                        res.end(JSON.stringify({ status: 'skipped' }));
                        return;
                    }
                    if (mainWindow && !mainWindow.isDestroyed()) {
                        const category = categorizeDomain(log.domain, log.title, log.url);
                        try {
                            safeSend(mainWindow, 'browser-tracking-event', {
                                type: 'live-log',
                                message: log.message,
                                level: log.level,
                                domain: log.domain,
                                url: log.url,
                                title: log.title,
                                category: category,
                                is_browser_focused: true,
                                timestamp: log.timestamp || Date.now()
                            });
                        } catch (_err) {}
                    }
                    res.writeHead(200, { 'Content-Type': 'application/json' });
                    res.end(JSON.stringify({ status: 'ok' }));
                }
                catch (err) {
                    res.writeHead(400, { 'Content-Type': 'application/json' });
                    res.end(JSON.stringify({ status: 'error', message: 'Invalid JSON' }));
                }
            });
        }
        else {
            res.writeHead(404, { 'Content-Type': 'application/json' });
            res.end(JSON.stringify({ status: 'not found' }));
        }
    });
    server.listen(browserServerPort, '127.0.0.1', () => {
        console.log(`[DeskFlow] 🌐 Browser tracking server started on port ${browserServerPort} (localhost only)`);
    });
    server.on('error', (err) => {
        if (err.code === 'EADDRINUSE') {
            console.warn(`[DeskFlow] ⚠️ Port ${browserServerPort} already in use, browser tracking unavailable`);
        }
        else {
            console.error('[DeskFlow] Browser server error:', err.message);
        }
    });
    browserServer = server;
    // FIX 2: Start the stale session flush timer
    startBrowserSessionFlushTimer();
}

// Tell the renderer to exit website mode immediately (website data rejected while a
// non-browser app is foreground). Prevents the dashboard staying "stuck" on a website.
function notifyRendererClearBrowser() {
    try {
        if (mainWindow && !mainWindow.isDestroyed()) {
            safeSend(mainWindow, 'browser-tracking-event', {
                type: 'clear',
                timestamp: Date.now()
            });
        }
    } catch (_err) {}
}

// Fresh OS foreground check: confirm the configured browser is REALLY the active window.
// The cached currentApp can lag behind a real app switch (active-win null/keepalive gaps),
// so we do one live active-win call before trusting extension website data.
// Returns true = browser confirmed foreground, false = confirmed non-browser foreground,
// null = indeterminate (no window / unknown), in which case we trust the cache.
async function freshForegroundIsBrowser(browsersList: string[]): Promise<boolean | null> {
    let raw = null;
    try {
        raw = await (0, active_win_1.default)();
    } catch (_) {
        if (process.platform === 'linux') {
            try {
                const fb = await linuxForeground_1.getLinuxForegroundWindow();
                if (fb && fb.title) raw = { owner: { name: fb.owner?.name || '', path: fb.owner?.path || '' }, title: fb.title };
            } catch (_) {}
        }
    }
    if (!raw) return null; // no active window (e.g. transition) — indeterminate
    const appName = (raw.owner?.name ?? raw.ownerName ?? '').replace(/\.exe$/i, '');
        if (!appName) return null;
        const lower = appName.toLowerCase();
        // If the OS foreground is DeskFlow itself, it means the user is back in the app
        if (lower === 'electron' || lower === 'deskflow' || lower === 'rheo') {
            return false;
        }
        // If it matches any configured browser ? still browser ? website data is valid
        if (browsersList.some((b: string) => isAppMatchingBrowser(appName, b))) {
            return true;
        }
        // Otherwise a real non-browser app is foreground ? reject website data
        return false;
}
// Handle incoming browser tracking data from extension
// FIX 1 + FIX 4: Use Map<string, LogEntry> keyed by domain, track time deltas properly
// FIX: Only track the MOST RECENTLY active tab, not all tabs
function handleBrowserData(data) {
    if (!isBrowserTrackingEnabled)
        return;
    if (!data.domain || !data.url)
        return;
    // Block all browser data when unfocused (phantom deltas from background tabs).
    // No bypass: the desktop app is the authority � website data is only recorded
    // while the browser is actually the foreground window.
    if (data.is_browser_focused === false) {
        return;
    }
    // Check if domain is excluded
    if (categorizeDomain(data.domain, data.title, data.url) === 'Excluded') {
        return;
    }
    // Notify focus manager of web activity
    if (focusManager) {
        focusManager.onWebActivity(data.domain);
    }
    // Resolve WHICH browser profile sent this payload (identity seam).
    const identity = resolveBrowserIdentity(data);
    // A profile the user paused must not contribute any data at all.
    if (!isProfileTrackingAllowed(identity.profileId, identity.browserName)) {
        return;
    }
    rememberExtensionSession(identity.profileId, identity.browserName, data.browserVersion);
    const sessionKey = browserSessionKey(identity, data.domain);
    const sessionDuration = data.active_duration_ms || 0;
    const dataTimestamp = data.timestamp ? new Date(data.timestamp).getTime() : Date.now();
    // Only log if session is meaningful (> 2 seconds)
    if (sessionDuration < 2000)
        return;
    // STRICT MODE: Only track the MOST RECENTLY active tab.
    // This is a PER-BROWSER rule: Chrome's background tabs must not pollute the
    // foreground, but Chrome and Firefox are separate browsers and must not
    // suppress each other (they can legitimately have the same domain open).
    const priorTab = lastActiveBrowserTabByProfile.get(sessionKey.split('::')[0]) ;
    if (priorTab && priorTab.domain !== data.domain) {
        const timeSinceLastActive = dataTimestamp - priorTab.timestamp;
        // If the last active was within last 30 seconds and this is a different domain, skip
        if (timeSinceLastActive < 30000) {
            console.log(`[DeskFlow] ⏭️ Skipped non-active browser tab: ${data.domain} (active: ${priorTab.domain})`);
            return;
        }
    }
    lastActiveBrowserTabByProfile.set(sessionKey.split('::')[0], { domain: data.domain, timestamp: dataTimestamp });
    // Update last active domain (global, for /status diagnostics only)
    lastActiveBrowserDomain = data.domain;
    lastActiveBrowserTimestamp = dataTimestamp;
    const existingSession = activeBrowserSessions.get(sessionKey);
    if (existingSession) {
        // FIX: Use explicit delta from extension if available (new behavior)
        // Otherwise calculate delta from last recorded duration (legacy behavior)
        let safeDelta;
        if (data.is_periodic && data.delta_ms) {
            // New behavior: extension sends explicit delta (time since last sync)
            safeDelta = Math.min(data.delta_ms, BROWSER_MAX_DELTA_MS);
            console.log(`[DeskFlow] 🔄 Periodic update for ${data.domain}: +${Math.floor(safeDelta / 1000)}s (delta)`);
        }
        else {
            // Legacy behavior: calculate delta from total duration
            const lastDuration = existingSession.duration_ms;
            const delta = sessionDuration - lastDuration;
            safeDelta = Math.min(Math.max(0, delta), BROWSER_MAX_DELTA_MS);
        }
        // Only update if there's actual new time (delta > 0 and reasonable)
        if (safeDelta > 1000) { // At least 1 second of new activity
            // Cap accumulated duration to prevent a single domain from exceeding
            // MAX_LOGGED_SESSION_MS (1 hour). Browser sessions update in-place via
            // the extension's periodic sync, so without a cap a domain visited for
            // hours would accumulate 5h+ in one DB row while the browser app itself
            // gets checkpointed in 2-min chunks � making website time > browser time.
            existingSession.duration_ms = Math.min(existingSession.duration_ms + safeDelta, MAX_LOGGED_SESSION_MS);
            // Liveness stamp. session.timestamp stays frozen at session START for
            // correct hourly attribution; this tracks "still receiving updates".
            (existingSession as any)._lastActivityAt = Date.now();
            existingSession.title = data.title || existingSession.title;
            // BUG FIX: Do NOT update timestamp on delta updates. The timestamp
            // represents session START time. Updating it to the latest sync time
            // caused the hourly distribution to attribute accumulated multi-hour
            // duration to the wrong (latest) hour instead of the hours where the
            // time was actually spent.
            // Update in SQLite � keep original timestamp, update duration + title + url
            if (!useJson) {
                try {
                    const updateStmt = db.prepare(`UPDATE logs SET duration_ms = ?, title = ?, url = ?, browser_name = COALESCE(?, browser_name), profile_id = COALESCE(?, profile_id) WHERE id = ?`);
                    updateStmt.run(existingSession.duration_ms, data.title || existingSession.title, data.sanitized_url || data.url, identity.browserName, identity.profileId, existingSession.id);
                    touchBrowserProfile(identity.profileId, identity.browserName, safeDelta);
                }
                catch (err) {
                    console.error('[DeskFlow] Browser session update failed:', err);
                }
            }
            else {
                // For JSON fallback: find and update the entry in jsonLogs
                const idx = jsonLogs.findIndex((l) => l.id === existingSession.id);
                if (idx !== -1) {
                    jsonLogs[idx].duration_ms = existingSession.duration_ms;
                    jsonLogs[idx].title = data.title || jsonLogs[idx].title;
                    jsonLogs[idx].url = data.sanitized_url || data.url;
                    // Keep original timestamp � don't update to latest sync time
                    saveJsonLogs();
                }
            }
            console.log(`[DeskFlow] Updated browser session: ${data.domain} -> ${Math.floor(existingSession.duration_ms / 1000)}s (+${Math.floor(safeDelta / 1000)}s)`);
            // Update browser_sessions aggregate table with the delta
            // Use original session timestamp for aggregate attribution
            if (!useJson && safeDelta > 0) {
                updateAggregates(existingSession.timestamp, existingSession.app, existingSession.category, safeDelta, data.domain, true);
            }
        }
    }
    else {
        // DEDUPLICATION: Check if a recent browser app entry exists (within 5s window)
        // If found, UPDATE it to use domain as app name instead of creating separate entry
        if (!useJson) {
            const recentBrowserApp = db.prepare(`
                SELECT id, app, domain, duration_ms FROM logs 
                WHERE is_browser_tracking = 1
                  AND domain IS NULL
                  AND timestamp > datetime('now', '-5 seconds')
                ORDER BY timestamp DESC
                LIMIT 1
            `).get();
            if (recentBrowserApp) {
                // Update existing entry with domain info
                db.prepare(`
                    UPDATE logs SET 
                      app = ?, domain = ?, url = ?, title = ?,
                      category = ?, browser_name = COALESCE(?, browser_name), profile_id = COALESCE(?, profile_id)
                    WHERE id = ?
                `).run(
                    data.domain, data.domain,
                    data.sanitized_url || data.url,
                    data.title || data.domain,
                    categorizeDomain(data.domain, data.title, data.url),
                    identity.browserName,
                    identity.profileId,
                    recentBrowserApp.id
                );
                console.log(`[DeskFlow] 🔗 Deduplicated browser entry: ${recentBrowserApp.app} → ${data.domain}`);
                touchBrowserProfile(identity.profileId, identity.browserName, newSessionDuration);
                // Still create in-memory session for delta tracking
                activeBrowserSessions.set(sessionKey, {
                    id: recentBrowserApp.id,
                    timestamp: data.timestamp || new Date().toISOString(),
                    app: data.domain,
                    category: categorizeDomain(data.domain, data.title, data.url),
                    duration_ms: 0,
                    title: data.title || data.domain,
                    domain: data.domain,
                    is_browser_tracking: true,
                    browser_name: identity.browserName,
                    profile_id: identity.profileId,
                    _lastActivityAt: Date.now()
                });
                return;
            }
        }
        // No active session for this domain — create new one
        let newSessionDuration;
        if (data.is_periodic) {
            newSessionDuration = Math.min(data.delta_ms || data.active_duration_ms, MAX_LOGGED_SESSION_MS);
            console.log(`[DeskFlow] 📝 First sync for ${data.domain}: creating new session with ${Math.floor((newSessionDuration || 0) / 1000)}s`);
        }
        newSessionDuration = Math.min(sessionDuration, MAX_LOGGED_SESSION_MS);
        if (sessionDuration > MAX_LOGGED_SESSION_MS) {
            console.warn(`[DeskFlow] ⚠️ Suspicious duration ${Math.floor(sessionDuration / 1000)}s for new session ${data.domain}, capping to 1 hour`);
        }
        const entry = {
            id: Date.now(),
            timestamp: data.timestamp || new Date().toISOString(),
            app: data.domain || data.app || 'Browser',
            category: categorizeDomain(data.domain, data.title, data.url),
            duration_ms: newSessionDuration,
            title: data.title || data.domain,
            project: undefined,
            url: data.sanitized_url || data.url,
            domain: data.domain,
            tab_id: data.tab_id,
            is_browser_tracking: true,
            browser_name: identity.browserName,
            profile_id: identity.profileId,
            _lastActivityAt: Date.now()
        };
        if (useJson) {
            jsonLogs.unshift(entry);
            if (jsonLogs.length > 50000)
                jsonLogs = jsonLogs.slice(0, 50000);
            saveJsonLogs();
        }
        else {
            try {
                const stmt = db.prepare(`
          INSERT INTO logs (timestamp, app, category, duration_ms, title, project, url, domain, tab_id, is_browser_tracking, browser_name, profile_id)
          VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        `);
                const result = stmt.run(entry.timestamp, entry.app, entry.category, entry.duration_ms, entry.title, entry.project, entry.url, entry.domain, entry.tab_id, 1, entry.browser_name, entry.profile_id);
                entry.id = result.lastInsertRowid;
            }
            catch (err) {
                console.error('[DeskFlow] Browser data insert failed:', err);
            }
        }
        touchBrowserProfile(identity.profileId, identity.browserName, newSessionDuration);
        updateAggregates(entry.timestamp, entry.app, entry.category, entry.duration_ms, data.domain, true);
        activeBrowserSessions.set(sessionKey, entry);
        console.log(`[DeskFlow] ✅ Browser logged: ${data.domain} → ${Math.floor(sessionDuration / 1000)}s (${identity.browserName || 'unknown browser'}${identity.profileId ? ` / ${identity.profileId.slice(0, 8)}` : ''})`);
    }
}
// FIX 2: Periodic flush of stale browser sessions (handles MV3 onSuspend unreliability)
// Called every 30 seconds to flush sessions that haven't been updated in 60+ seconds
let browserSessionFlushInterval = null;
function startBrowserSessionFlushTimer() {
    if (browserSessionFlushInterval)
        clearInterval(browserSessionFlushInterval);
    browserSessionFlushInterval = setInterval(() => {
        const now = Date.now();
        const STALE_THRESHOLD_MS = 60000; // 60 seconds
        for (const [key, session] of activeBrowserSessions.entries()) {
            // Use _lastActivityAt, NOT session.timestamp.
            // session.timestamp is deliberately the SESSION START time (it is never
            // refreshed on delta updates, so hourly attribution stays correct), which
            // meant this timer used to evict a session that was still receiving
            // updates the instant it passed 60s old — fragmenting one browsing
            // session into many rows and losing the accumulated in-memory duration.
            const lastActivity = (session as any)._lastActivityAt
                ?? new Date(session.timestamp).getTime();
            const sessionAge = now - lastActivity;
            if (sessionAge > STALE_THRESHOLD_MS) {
                // Session is stale — remove from active map (it's already persisted in SQLite)
                activeBrowserSessions.delete(key);
                lastActiveBrowserTabByProfile.delete(String(key).split('::')[0]);
                console.log(`[DeskFlow] 🧹 Flushed stale browser session: ${key} (${Math.floor(session.duration_ms / 1000)}s)`);
            }
        }
        reapDisconnectedProfiles(now);
    }, 30000); // Check every 30 seconds
}

/**
 * Phase 2.2/2.3 — make "connected" mean "spoke in the last 60s".
 * is_connected used to be set to 1 once and never cleared, so every profile
 * ever seen displayed a permanent green dot whether or not the extension was
 * even running. Derive it from last_seen_at instead of trusting the column.
 */
function reapDisconnectedProfiles(now = Date.now()) {
    if (!db)
        return;
    try {
        // Mark anything whose last_seen_at is older than the TTL as disconnected.
        const res = db.prepare(`
            UPDATE browser_profiles
            SET is_connected = 0, updated_at = datetime('now','localtime')
            WHERE is_connected = 1
              AND (
                last_seen_at IS NULL
                OR (julianday('now','localtime') - julianday(last_seen_at)) * 86400000 > ?
              )
        `).run(PROFILE_CONNECT_TTL_MS);
        if (res.changes > 0)
            console.log(`[DeskFlow] 📴 Marked ${res.changes} browser profile(s) disconnected (no heartbeat in ${PROFILE_CONNECT_TTL_MS / 1000}s)`);
    }
    catch (err) {
        console.error('[DeskFlow] reapDisconnectedProfiles error:', err);
    }
    // Drop in-memory sessions for extensions that went silent entirely.
    for (const [profileId, sess] of extensionSessions.entries()) {
        if (now - sess.lastSeen > PROFILE_CONNECT_TTL_MS * 4)
            extensionSessions.delete(profileId);
    }
}
function stopBrowserSessionFlushTimer() {
    if (browserSessionFlushInterval) {
        clearInterval(browserSessionFlushInterval);
        browserSessionFlushInterval = null;
    }
}
function validatePeriod(period, dateOffset) {
    const validPeriods = ['today', 'week', '7day', '30day', 'all'];
    if (!validPeriods.includes(period)) {
        console.warn('[DeskFlow] Invalid period:', period, '— defaulting to today');
        return ['today', 0];
    }
    const offset = Math.max(0, Math.min(100, Number(dateOffset) || 0));
    return [period, offset];
}
function computeBrowserDateRange(period, dateOffset) {
    [period, dateOffset] = validatePeriod(period, dateOffset);
    const now = new Date();
    if (period === 'today') {
        const d = new Date(now);
        d.setDate(d.getDate() - dateOffset);
        const start = new Date(d.getFullYear(), d.getMonth(), d.getDate()).toISOString();
        const end = new Date(d);
        end.setHours(23, 59, 59, 999);
        return { startDate: start, endDate: end.toISOString() };
    }
    if (period === 'week') {
        const weekStart = new Date(now);
        const day = weekStart.getDay();
        const diff = day === 0 ? 6 : day - 1;
        weekStart.setDate(weekStart.getDate() - diff - dateOffset * 7);
        weekStart.setHours(0, 0, 0, 0);
        const weekEnd = new Date(weekStart);
        weekEnd.setDate(weekEnd.getDate() + 6);
        weekEnd.setHours(23, 59, 59, 999);
        return { startDate: weekStart.toISOString(), endDate: weekEnd.toISOString() };
    }
    if (period === '7day') {
        const end = new Date(now.getTime() - dateOffset * 7 * 24 * 60 * 60 * 1000);
        end.setHours(23, 59, 59, 999);
        const start = new Date(end.getTime() - 6 * 24 * 60 * 60 * 1000);
        return { startDate: start.toISOString(), endDate: end.toISOString() };
    }
    if (period === 'month') {
        const targetMonth = new Date(now.getFullYear(), now.getMonth() - dateOffset, 1);
        const monthEnd = new Date(now.getFullYear(), now.getMonth() - dateOffset + 1, 0, 23, 59, 59, 999);
        return { startDate: targetMonth.toISOString(), endDate: monthEnd.toISOString() };
    }
    if (period === '30day') {
        const end = new Date(now.getTime() - dateOffset * 30 * 24 * 60 * 60 * 1000);
        end.setHours(23, 59, 59, 999);
        const start = new Date(end.getTime() - 29 * 24 * 60 * 60 * 1000);
        return { startDate: start.toISOString(), endDate: end.toISOString() };
    }
    return { startDate: null, endDate: null };
}
// Get browser activity logs
function getBrowserLogs(period, dateOffset = 0) {
    const { startDate, endDate } = computeBrowserDateRange(period, dateOffset);

    if (useJson) {
        let logs = jsonLogs.filter((log) => log.is_browser_tracking);
        if (startDate) {
            logs = logs.filter(l => l.timestamp >= startDate);
        }
        if (endDate) {
            logs = logs.filter(l => l.timestamp <= endDate);
        }
        return logs.slice(0, 200);
    }
    try {
        let query = `SELECT * FROM logs WHERE is_browser_tracking = 1`;
        const params: string[] = [];
        if (startDate) {
            query += ` AND timestamp >= ?`;
            params.push(startDate);
        }
        if (endDate) {
            query += ` AND timestamp <= ?`;
            params.push(endDate);
        }
        // No limit — frontend needs all matching rows for daily/monthly chart aggregation
        query += ` ORDER BY id DESC`;
        const stmt = db.prepare(query);
        return stmt.all(...params);
    }
    catch (err) {
        console.error('[DeskFlow] get-browser-logs error:', err);
        return [];
    }
}
// Get browser stats grouped by domain
function getBrowserDomainStats(period, dateOffset = 0) {
    const { startDate, endDate } = computeBrowserDateRange(period, dateOffset);

    if (useJson) {
        let logs = jsonLogs.filter((log) => log.is_browser_tracking);
        if (startDate) {
            logs = logs.filter(l => l.timestamp >= startDate);
        }
        if (endDate) {
            logs = logs.filter(l => l.timestamp <= endDate);
        }
        const stats = new Map();
        logs.forEach((log) => {
            const browser = log.browser_name || '';
            const key = `${log.domain || 'unknown'}|${browser}`;
            const existing = stats.get(key) || { total_ms: 0, sessions: 0, domain: log.domain || 'unknown', browser_name: browser || undefined, category: log.category || 'Other', title: log.title || log.domain || 'unknown' };
            existing.total_ms += log.duration_ms;
            existing.sessions += 1;
            stats.set(key, existing);
        });
        return Array.from(stats.values()).sort((a, b) => b.total_ms - a.total_ms);
    }
    try {
        let query = `
      SELECT domain, browser_name, category, SUM(duration_ms) as total_ms, COUNT(*) as sessions, MAX(title) as title
      FROM logs 
      WHERE is_browser_tracking = 1 AND domain IS NOT NULL
    `;
        const params: string[] = [];
        if (startDate) {
            query += ` AND timestamp >= ?`;
            params.push(startDate);
        }
        if (endDate) {
            query += ` AND timestamp <= ?`;
            params.push(endDate);
        }
        query += ` GROUP BY domain, browser_name ORDER BY total_ms DESC`;
        const stmt = db.prepare(query);
        return stmt.all(...params);
    }
    catch (err) {
        console.error('[DeskFlow] get-browser-domain-stats error:', err);
        return [];
    }
}
// Get browser stats grouped by category
function getBrowserCategoryStats(period, dateOffset = 0) {
    const { startDate, endDate } = computeBrowserDateRange(period, dateOffset);

    if (useJson) {
        let logs = jsonLogs.filter((log) => log.is_browser_tracking);
        if (startDate) {
            logs = logs.filter(l => l.timestamp >= startDate);
        }
        if (endDate) {
            logs = logs.filter(l => l.timestamp <= endDate);
        }
        const stats = new Map();
        logs.forEach((log) => {
            const key = log.category || 'Other';
            const existing = stats.get(key) || { total_ms: 0, sessions: 0, category: key };
            existing.total_ms += log.duration_ms;
            existing.sessions += 1;
            stats.set(key, existing);
        });
        return Array.from(stats.values()).sort((a, b) => b.total_ms - a.total_ms);
    }
    try {
        let query = `
      SELECT category, SUM(duration_ms) as total_ms, COUNT(*) as sessions
      FROM logs 
      WHERE is_browser_tracking = 1 AND category IS NOT NULL
    `;
        const params: string[] = [];
        if (startDate) {
            query += ` AND timestamp >= ?`;
            params.push(startDate);
        }
        if (endDate) {
            query += ` AND timestamp <= ?`;
            params.push(endDate);
        }
        query += ` GROUP BY category ORDER BY total_ms DESC`;
        const stmt = db.prepare(query);
        return stmt.all(...params);
    }
    catch (err) {
        console.error('[DeskFlow] get-browser-category-stats error:', err);
        return [];
    }
}
// ═══════════════════════════════════════════════════════════════
// CONDUCTOR — multi-agent orchestration IPC handlers
// ═══════════════════════════════════════════════════════════════
let conductorService: any = null;
function getConductorService() {
  if (conductorService) return conductorService;
  try {
    const { ConductorService } = require('./services/conductor/ConductorService');
    const { BrowserWindow } = require('electron');
    conductorService = new ConductorService({
      spawnAgentTerminal: async (id: string, cwd: string, cols: number, rows: number, agentType?: string) => {
        // [CONDUCTOR-FIX] Two-phase spawn: PTY created in MAIN, renderer view attaches via broadcast.
        const spawnResult = terminalManager.spawn(id, cwd, cols, rows);
        if (!spawnResult.success) return { success: false, error: spawnResult.error };
        // Broadcast to ALL windows (not just the first) so any TerminalPage can attach the xterm view.
        const win = BrowserWindow.getAllWindows().find((w: any) => !w.isDestroyed());
        if (win) safeSend(win, 'terminal:spawn-for-conductor', { terminalId: id, cwd, cols, rows, agentType });
        return { success: true };
      },
      writeTerminal: (id: string, data: string) => {
        try { terminalManager.write(id, data); } catch {}
      },
      killTerminal: (id: string) => {
        try { terminalManager.kill(id); } catch {}
      },
      isAgentReady: (id: string) => terminalManager.has(id),
      broadcast: (event: string, ...args: any[]) => {
        for (const win of BrowserWindow.getAllWindows()) {
          if (!win.isDestroyed()) safeSend(win, event, ...args);
        }
      },
    });
    return conductorService;
  } catch (e: any) {
    console.error('[DeskFlow] Failed to init ConductorService:', e.message);
    return null;
  }
}

electron_1.ipcMain.handle('conductor:start', async (_event, opts: any) => {
  const svc = getConductorService();
  if (!svc) return { success: false, error: 'ConductorService not available' };
  try {
    // Translate MissionWizard params to ConductorService params
    const agentAssignments = opts.agentAssignments || {};
    const firstRole = Object.keys(agentAssignments)[0];
    const firstProvider = firstRole ? agentAssignments[firstRole] : null;
    const agentType = opts.agentType || (firstProvider?.provider || firstProvider?.name || 'claude');
    const snapshot = await svc.startMission({
      repoRoot: opts.repoRoot || opts.repoPath || process.cwd(),
      objective: opts.objective || '',
      agentType,
      autonomyLevel: opts.autonomyLevel || 'L3',
    });
    return { success: true, data: snapshot };
  } catch (e: any) { return { success: false, error: e.message }; }
});

