// Day context for the manual-assign editor: everything tracked on a given
// LOCAL day (logs + external sessions) so the UI can show what's occupied
// vs what's free, plus existing manual assignments for that day.
electron_1.ipcMain.handle('manual-assign:day-context', (event, { date } = {}) => {
    if (useJson) return { tracked: [], manual: [] };
    try {
        const dayStart = new Date(date + 'T00:00:00');
        const dayEnd = new Date(dayStart.getTime() + 24 * 60 * 60 * 1000);
        const dayStartIso = dayStart.toISOString();
        const dayEndIso = dayEnd.toISOString();

        const logs = db.prepare(`SELECT timestamp, duration_ms, app FROM logs WHERE timestamp >= ? AND timestamp < ?`).all(dayStartIso, dayEndIso);
        const externals = db.prepare(`SELECT started_at, ended_at FROM external_sessions WHERE ended_at IS NOT NULL AND started_at < ? AND ended_at > ?`).all(dayEndIso, dayStartIso);
        const manual = db.prepare(`SELECT id, date, started_at, ended_at, duration_seconds, mode, app, category FROM manual_time_assignments WHERE date = ?`).all(date);

        const tracked = [];
        for (const log of logs) {
            const start = new Date(log.timestamp).getTime();
            const end = start + Math.max((log.duration_ms || 0), 1000);
            tracked.push({ started_at: new Date(start).toISOString(), ended_at: new Date(end).toISOString(), app: log.app || null });
        }
        for (const es of externals) {
            const start = Math.max(new Date(es.started_at).getTime(), dayStart.getTime());
            const end = Math.min(new Date(es.ended_at).getTime(), dayEnd.getTime());
            if (end > start) tracked.push({ started_at: new Date(start).toISOString(), ended_at: new Date(end).toISOString() });
        }

        return { tracked, manual };
    }
    catch (err) {
        console.error('[DeskFlow] manual-assign:day-context error:', err);
        return { tracked: [], manual: [] };
    }
});

electron_1.ipcMain.handle('manual-assign:create', (event, data = {}) => {
    if (useJson) return { ok: false, error: 'JSON storage mode does not support manual assignments' };
    try {
        const { startedAt, endedAt, mode = 'custom', app = null, category = null } = data;
        if (!startedAt || !endedAt) return { ok: false, error: 'Missing startedAt/endedAt' };

        const startMs = new Date(startedAt).getTime();
        const endMs = new Date(endedAt).getTime();
        if (!isFinite(startMs) || !isFinite(endMs)) return { ok: false, error: 'Invalid timestamps' };
        if (endMs <= startMs) return { ok: false, error: 'endedAt must be after startedAt' };

        const durationSeconds = Math.floor((endMs - startMs) / 1000);
        const dateStr = startedAt.split('T')[0];

        // NEVER replace real tracked time: reject if the span overlaps any
        // auto-tracked log, external session, or existing manual assignment.
        const overlapsLog = db.prepare(`
            SELECT 1 FROM logs
            WHERE timestamp < ? AND (timestamp + MAX(duration_ms, 1000)) > ?
            LIMIT 1
        `).get(endedAt, startedAt);
        if (overlapsLog) return { ok: false, error: 'Span overlaps auto-tracked time — only empty spans can be filled' };

        const overlapsExternal = db.prepare(`
            SELECT 1 FROM external_sessions
            WHERE started_at < ? AND ended_at IS NOT NULL AND ended_at > ?
            LIMIT 1
        `).get(endedAt, startedAt);
        if (overlapsExternal) return { ok: false, error: 'Span overlaps an external activity — only empty spans can be filled' };

        const overlapsManual = db.prepare(`
            SELECT 1 FROM manual_time_assignments
            WHERE started_at < ? AND ended_at > ?
            LIMIT 1
        `).get(endedAt, startedAt);
        if (overlapsManual) return { ok: false, error: 'Span overlaps an existing manual assignment' };

        // Every manual entry gets a concrete app. Without this the row would be
        // invisible to per-app breakdowns, which is exactly the bug that made a
        // backfilled month render as one anonymous grey slab.
        const appName = (app && String(app).trim()) || 'Manual time';
        const catName = (category && String(category).trim()) || 'other';

        // Insert the aggregate-visible row FIRST so the existing AFTER INSERT
        // triggers (trg_update_daily / trg_update_hourly) pick it up exactly as
        // they would for real tracked time. This is what makes manual fill show up
        // in every chart, timeline and per-app breakdown with no query changes.
        const logInfo = db.prepare(`
            INSERT INTO logs (timestamp, app, category, duration_ms, title, is_browser_tracking, source)
            VALUES (?, ?, ?, ?, ?, 0, 'manual')
        `).run(startedAt, appName, catName, durationSeconds * 1000, `Manual entry: ${appName}`);

        const info = db.prepare(`
            INSERT INTO manual_time_assignments (date, started_at, ended_at, duration_seconds, mode, app, category, log_id)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?)
        `).run(dateStr, startedAt, endedAt, durationSeconds, mode === 'random' ? 'random' : 'custom', appName, catName, Number(logInfo.lastInsertRowid));

        // Purge any legacy 'Manual time' pseudo-app aggregate so it cannot
        // double-count against the real per-app rows just written.
        syncManualStats(dateStr);
        recomputeAppAggregate(dateStr, appName);

        console.log(`[DeskFlow] ✅ Manual assignment ${info.lastInsertRowid} → log ${logInfo.lastInsertRowid}: ${durationSeconds}s ${appName} (${mode}) on ${dateStr}`);
        return { ok: true, id: Number(info.lastInsertRowid), logId: Number(logInfo.lastInsertRowid), durationSeconds };
    }
    catch (err) {
        console.error('[DeskFlow] manual-assign:create error:', err);
        return { ok: false, error: String(err && err.message || err) };
    }
});

electron_1.ipcMain.handle('manual-assign:delete', (event, { id } = {}) => {
    if (useJson) return { ok: false, error: 'JSON storage mode does not support manual assignments' };
    try {
        const row = db.prepare(`SELECT date, app, log_id FROM manual_time_assignments WHERE id = ?`).get(id);
        if (!row) return { ok: false, error: 'Assignment not found' };
        db.prepare(`DELETE FROM manual_time_assignments WHERE id = ?`).run(id);

        // Remove the mirrored `logs` row too, or the deleted minutes keep showing
        // up in every chart forever. Guarded on source='manual' so a row can only
        // ever remove its own generated twin, never real tracked time.
        if (row.log_id) {
            db.prepare(`DELETE FROM logs WHERE id = ? AND source = 'manual'`).run(row.log_id);
        }

        // stats_daily / stats_hourly have no DELETE trigger, so repair them by hand.
        purgeStatsRow(row.date, row.app || 'Manual time');
        syncManualStats(row.date);
        if (row.app) recomputeAppAggregate(row.date, row.app);

        console.log(`[DeskFlow] Manual assignment ${id} deleted (${row.date}, ${row.app})`);
        return { ok: true };
    }
    catch (err) {
        console.error('[DeskFlow] manual-assign:delete error:', err);
        return { ok: false, error: String(err && err.message || err) };
    }
});

// Removes one (date, app) pair from stats_daily and stats_hourly and re-inserts the
// correct totals derived from `logs`. The AFTER INSERT triggers that normally
// maintain these two tables have no DELETE counterpart, so without this a deleted
// manual row would leave a permanent phantom total behind.
function purgeStatsRow(dateStr, app) {
    if (useJson || !ensureDb()) return;
    try {
        // Daily: one row per (date, app).
        db.prepare(`DELETE FROM stats_daily WHERE date = ? AND app_name = ?`).run(dateStr, app);
        const dayAgg = db.prepare(`
            SELECT COALESCE(SUM(duration_ms), 0) AS total_ms, COUNT(*) AS cnt
            FROM logs
            WHERE date(timestamp) = ? AND app = ? AND duration_ms > 0
        `).get(dateStr, app);
        const dayTotal = Math.floor((dayAgg?.total_ms || 0) / 1000);
        if (dayTotal > 0) {
            const cat = db.prepare(`
                SELECT COALESCE(MIN(category), 'other') AS c FROM logs
                WHERE date(timestamp) = ? AND app = ? AND duration_ms > 0
            `).get(dateStr, app)?.c || 'other';
            db.prepare(`
                INSERT INTO stats_daily (date, app_name, app_type, category, total_seconds, session_count)
                VALUES (?, ?, 'app', ?, ?, ?)
            `).run(dateStr, app, cat, dayTotal, dayAgg?.cnt || 0);
        }

        // Hourly: must stay one row per (date, hour, app) — rebuilding it as a
        // single row would destroy the hour breakdown the charts read.
        db.prepare(`DELETE FROM stats_hourly WHERE date = ? AND app_name = ?`).run(dateStr, app);
        const hours = db.prepare(`
            SELECT CAST(STRFTIME('%H', timestamp) AS INTEGER) AS hour,
                   COALESCE(SUM(duration_ms), 0) AS total_ms,
                   COUNT(*) AS cnt
            FROM logs
            WHERE date(timestamp) = ? AND app = ? AND duration_ms > 0
            GROUP BY CAST(STRFTIME('%H', timestamp) AS INTEGER)
        `).all(dateStr, app);
        const hourCat = db.prepare(`
            SELECT COALESCE(MIN(category), 'other') AS c FROM logs
            WHERE date(timestamp) = ? AND app = ? AND duration_ms > 0
        `).get(dateStr, app)?.c || 'other';
        const insertHour = db.prepare(`
            INSERT INTO stats_hourly (date, hour, app_name, app_type, category, total_seconds, session_count)
            VALUES (?, ?, ?, 'app', ?, ?, ?)
        `);
        for (const h of hours) {
            const total = Math.floor((h.total_ms || 0) / 1000);
            if (total <= 0) continue;
            insertHour.run(dateStr, h.hour, app, hourCat, total, h.cnt || 0);
        }
    }
    catch (err) {
        console.error('[DeskFlow] purgeStatsRow error:', err);
    }
}

electron_1.ipcMain.handle('start-external-session', (event, activityId) => {
    if (useJson) return { success: false };
    try {
        const active = db.prepare(`
            SELECT id, activity_id FROM external_sessions
            WHERE ended_at IS NULL
            ORDER BY started_at DESC
            LIMIT 1
        `).get();
        if (active) {
            if (active.activity_id.toString() === activityId) {
                return { success: true, sessionId: active.id.toString() };
            }
            const startedAt = db.prepare(`SELECT started_at FROM external_sessions WHERE id = ?`).get(active.id);
            if (startedAt) {
                const durationSeconds = Math.floor((Date.now() - new Date(startedAt.started_at).getTime()) / 1000);
                db.prepare(`UPDATE external_sessions SET ended_at = ?, duration_seconds = ? WHERE id = ?`)
                    .run(new Date().toISOString(), durationSeconds, active.id);
            }
        }
        const result = db.prepare(`
            INSERT INTO external_sessions (activity_id, started_at)
            VALUES (?, ?)
        `).run(activityId, new Date().toISOString());
        return { success: true, sessionId: result.lastInsertRowid.toString() };
    } catch (err) {
        console.error('[DeskFlow] Failed to start external session:', err);
        return { success: false };
    }
});

electron_1.ipcMain.handle('stop-external-session', (event, sessionId, endTime, deviceOffToSleepSeconds, wakeUpToAppSeconds) => {
    if (useJson) return { success: false, duration: 0 };
    try {
        const now = endTime ? new Date(endTime) : new Date();
        const session = db.prepare('SELECT * FROM external_sessions WHERE id = ?').get(sessionId);
        if (!session) return { success: false, duration: 0 };
        
        const startedAt = new Date(session.started_at);
        let durationSeconds = Math.floor((now.getTime() - startedAt.getTime()) / 1000);

        // Sanity cap: total duration cannot exceed 24 hours
        if (durationSeconds > 24 * 3600) {
            durationSeconds = 24 * 3600;
        }

        // Cap latencies to 4 hours max
        const offSleep = deviceOffToSleepSeconds !== undefined ? Math.min(deviceOffToSleepSeconds, 4 * 3600) : (session.device_off_to_sleep_seconds || 0);
        const wakeApp = wakeUpToAppSeconds !== undefined ? Math.min(wakeUpToAppSeconds, 4 * 3600) : (session.wake_up_to_app_seconds || 0);
        db.prepare(`
            UPDATE external_sessions 
            SET ended_at = ?, duration_seconds = ?, device_off_to_sleep_seconds = ?, wake_up_to_app_seconds = ?
            WHERE id = ?
        `).run(now.toISOString(), durationSeconds, offSleep, wakeApp, sessionId);
        
        return { success: true, duration: durationSeconds };
    } catch (err) {
        console.error('[DeskFlow] Failed to stop external session:', err);
        return { success: false, duration: 0 };
    }
});

electron_1.ipcMain.handle('update-external-session', (event, sessionId, updates: { started_at?: string; ended_at?: string; duration_seconds?: number; activity_id?: number }) => {
    if (useJson) return { success: false };
    try {
        const fields: string[] = [];
        const values: any[] = [];
        if (updates.started_at !== undefined) { fields.push('started_at = ?'); values.push(updates.started_at); }
        if (updates.ended_at !== undefined) { fields.push('ended_at = ?'); values.push(updates.ended_at); }
        if (updates.duration_seconds !== undefined) { fields.push('duration_seconds = ?'); values.push(updates.duration_seconds); }
        if (updates.activity_id !== undefined) { fields.push('activity_id = ?'); values.push(updates.activity_id); }
        if (fields.length === 0) return { success: true };
        values.push(sessionId);
        db.prepare(`UPDATE external_sessions SET ${fields.join(', ')} WHERE id = ?`).run(...values);
        return { success: true };
    } catch (err) {
        console.error('[DeskFlow] Failed to update external session:', err);
        return { success: false };
    }
});

