electron_1.ipcMain.handle('add-manual-sleep', (event, sleepData: { started_at: string; ended_at: string; device_off_to_sleep_seconds?: number; wake_up_to_app_seconds?: number }) => {
    if (useJson) return { success: false };
    try {
        const startTime = new Date(sleepData.started_at);
        const endTime = new Date(sleepData.ended_at);
        let durationSeconds = Math.floor((endTime.getTime() - startTime.getTime()) / 1000);
        
        if (durationSeconds <= 0) {
            return { success: false, error: 'End time must be after start time' };
        }

        // Sanity cap: total duration cannot exceed 24 hours
        if (durationSeconds > 24 * 3600) {
            durationSeconds = 24 * 3600;
        }

        // Cap pre-sleep latency to 4 hours max
        const preSleep = Math.min(sleepData.device_off_to_sleep_seconds || 0, 4 * 3600);
        // Cap post-wake latency to 4 hours max
        const postWake = Math.min(sleepData.wake_up_to_app_seconds || 0, 4 * 3600);
        
        const sleepActivity = db.prepare(`
            SELECT id FROM external_activities WHERE type = 'sleep' LIMIT 1
        `).get() as any;
        
        if (!sleepActivity) {
            return { success: false, error: 'No sleep activity found' };
        }
        
        const result = db.prepare(`
            INSERT INTO external_sessions (activity_id, started_at, ended_at, duration_seconds, device_off_to_sleep_seconds, wake_up_to_app_seconds)
            VALUES (?, ?, ?, ?, ?, ?)
        `).run(
            sleepActivity.id, 
            startTime.toISOString(), 
            endTime.toISOString(), 
            durationSeconds,
            preSleep,
            postWake
        );
        
        return { success: true, sessionId: result.lastInsertRowid.toString() };
    } catch (err) {
        console.error('[DeskFlow] Failed to add manual sleep:', err);
        return { success: false };
    }
});

electron_1.ipcMain.handle('get-sleep-for-date', (event, dateStr: string) => {
    if (useJson) return null;
    try {
        const sleepActivity = db.prepare(`SELECT id FROM external_activities WHERE type = 'sleep' LIMIT 1`).get() as any;
        if (!sleepActivity) return null;

// Match by the stationary sleep day used by the popup and chart.
        // Sleep date = the calendar day the session BELONGS to (bedtime past
        // midnight before 12:00 belongs to the PREVIOUS day's sleep).
        // Primary window: [date 12:00, date+1 12:00) on started_at, which covers
        // bedtime Aug 11 22:00 AND bedtime Aug 12 03:03 (both Aug 11's sleep).
        // Also match the RAW bedtime calendar day (started_at within [date 00:00, date+1 00:00))
        // so searching the raw bedtime/wake-up date still finds the sleep.
        const winStart = new Date(dateStr + 'T12:00:00');
        const winEnd = new Date(dateStr + 'T12:00:00');
        winEnd.setDate(winEnd.getDate() + 1);
        const dayStart = new Date(dateStr + 'T00:00:00');
        const dayEnd = new Date(dateStr + 'T00:00:00');
        dayEnd.setDate(dayEnd.getDate() + 1);
        const sessions = db.prepare(`
            SELECT * FROM external_sessions
            WHERE activity_id = ? AND ended_at IS NOT NULL
              AND ((started_at >= ? AND started_at < ?) OR (started_at >= ? AND started_at < ?))
            ORDER BY started_at ASC
        `).all(sleepActivity.id, winStart.toISOString(), winEnd.toISOString(), dayStart.toISOString(), dayEnd.toISOString()) as any[];
        const session = sessions[0] || null;

        if (!session) return null;

        return {
            id: session.id,
            started_at: session.started_at,
            ended_at: session.ended_at,
            device_off_to_sleep_seconds: session.device_off_to_sleep_seconds || 0,
            wake_up_to_app_seconds: session.wake_up_to_app_seconds || 0,
        };
    } catch (err) {
        console.error('[DeskFlow] Failed to get sleep for date:', err);
        return null;
    }
});

