electron_1.ipcMain.handle('save-productivity-session', (event, session: {
    started_at: string;
    ended_at?: string;
    duration_seconds?: number;
    app_name?: string;
    category?: string;
    is_streak?: boolean;
}) => {
    if (useJson) return null;
    try {
        const started = new Date(session.started_at);
        const day = started.getDay();
        const weekNum = getWeekNumber(started);
        const month = `${started.getFullYear()}-${started.getMonth() + 1}`;

        const result = db.prepare(`
            INSERT INTO productivity_sessions (started_at, ended_at, duration_seconds, app_name, category, is_streak, day, week_number, month)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
        `).run(
            session.started_at,
            session.ended_at || null,
            session.duration_seconds || 0,
            session.app_name || null,
            session.category || null,
            session.is_streak ? 1 : 0,
            day,
            weekNum,
            month
        );

        return { id: result.lastInsertRowid };
    } catch (err) {
        console.error('[DeskFlow] Failed to save productivity session:', err);
        return null;
    }
});

electron_1.ipcMain.handle('get-productivity-sessions', (event, opts: {
    period?: 'today' | 'week' | '7day' | 'month' | '30day' | 'all';
    dateOffset?: number;
    minDuration?: number;
    limit?: number;
    offset?: number;
} = {}) => {
    if (useJson) return { sessions: [], stats: { todayBest: 0, weekBest: 0, allTimeBest: 0, todayTotal: 0, weekTotal: 0, longestStreak: 0 } };
    try {
        const { period = 'all', dateOffset = 0, minDuration = 0, limit = 50, offset = 0 } = opts;
        let dateFilter = '';
        const now = new Date();

        const periodDays = period === 'today' ? 1 : period === 'week' || period === '7day' ? 7 : period === 'month' || period === '30day' ? 30 : 0;
        const shifted = new Date(now.getTime() + dateOffset * periodDays * 24 * 60 * 60 * 1000);

        if (period === 'today') {
            const today = shifted.toISOString().split('T')[0];
            dateFilter = `AND date(ps.started_at) = '${today}'`;
        } else if (period === 'week' || period === '7day') {
            const weekAgo = new Date(shifted.getTime() - 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0];
            dateFilter = `AND date(ps.started_at) >= '${weekAgo}'`;
        } else if (period === 'month' || period === '30day') {
            const monthAgo = new Date(shifted.getTime() - 30 * 24 * 60 * 60 * 1000).toISOString().split('T')[0];
            dateFilter = `AND date(ps.started_at) >= '${monthAgo}'`;
        }

        const sessions = db.prepare(`
            SELECT ps.*,
                (SELECT MAX(duration_seconds) FROM productivity_sessions WHERE date(started_at) = date(ps.started_at)) as day_best,
                (SELECT SUM(duration_seconds) FROM productivity_sessions WHERE date(started_at) = date(ps.started_at)) as day_total
            FROM productivity_sessions ps
            WHERE ps.duration_seconds >= ? ${dateFilter}
            ORDER BY ps.duration_seconds DESC, ps.started_at DESC
            LIMIT ? OFFSET ?
        `).all(minDuration, limit, offset);

        const stats = (() => {
            const today = shifted.toISOString().split('T')[0];
            const weekAgo = new Date(shifted.getTime() - 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0];

            const todayBest = db.prepare(`
                SELECT MAX(duration_seconds) as best FROM productivity_sessions WHERE date(started_at) = ? AND duration_seconds >= ?
            `).get(today, minDuration) as any;

            const weekBest = db.prepare(`
                SELECT MAX(duration_seconds) as best FROM productivity_sessions WHERE date(started_at) >= ? AND duration_seconds >= ?
            `).get(weekAgo, minDuration) as any;

            const allTimeBest = db.prepare(`
                SELECT MAX(duration_seconds) as best FROM productivity_sessions WHERE duration_seconds >= ?
            `).get(minDuration) as any;

            const todayTotal = db.prepare(`
                SELECT COALESCE(SUM(duration_seconds), 0) as total FROM productivity_sessions WHERE date(started_at) = ? AND duration_seconds >= ?
            `).get(today, minDuration) as any;

            const weekTotal = db.prepare(`
                SELECT COALESCE(SUM(duration_seconds), 0) as total FROM productivity_sessions WHERE date(started_at) >= ? AND duration_seconds >= ?
            `).get(weekAgo, minDuration) as any;

            return {
                todayBest: todayBest?.best || 0,
                weekBest: weekBest?.best || 0,
                allTimeBest: allTimeBest?.best || 0,
                todayTotal: todayTotal?.total || 0,
                weekTotal: weekTotal?.total || 0,
                longestStreak: 0
            };
        })();

        return { sessions, stats };
    } catch (err) {
        console.error('[DeskFlow] Failed to get productivity sessions:', err);
        return { sessions: [], stats: { todayBest: 0, weekBest: 0, allTimeBest: 0, todayTotal: 0, weekTotal: 0, longestStreak: 0 } };
    }
});

// --- IPC: get-longest-focus ----------------------------------
// Finds the top 3 longest continuous productive sessions for today / this week / all time.
// Merges consecutive same-app logs within a 10s gap.
electron_1.ipcMain.handle('get-longest-focus', async () => {
    ensureDb();
    try {
        const tierMap = getTierMap(db);

        function findTopSessions(logs: any[], limit = 3): any[] {
            const sessions: any[] = [];
            let current: any = null;
            for (let i = 0; i < logs.length; i++) {
                const log = logs[i];
                const app = log.is_browser_tracking ? (log.domain || log.app) : log.app;
                const tier = tierMap.get(app) || 'neutral';
                const logTime = new Date(log.timestamp).getTime();
                const logEnd = logTime + (log.duration_ms || 0);

                if (tier !== 'productive') {
                    if (current) sessions.push({ ...current });
                    current = null;
                    continue;
                }

                if (current && logTime - current.endTime < 10000) {
                    current.durationMs += log.duration_ms || 0;
                    current.endTime = logEnd;
                    if (!current.apps.includes(app)) current.apps.push(app);
                } else {
                    if (current) sessions.push({ ...current });
                    current = {
                        apps: [app],
                        category: log.category || 'Other',
                        startTime: logTime,
                        endTime: logEnd,
                        durationMs: log.duration_ms || 0,
                        title: log.title || '',
                    };
                }
            }
            if (current) sessions.push({ ...current });
            sessions.sort((a: any, b: any) => b.durationMs - a.durationMs);
            return sessions.slice(0, limit);
        }

        // Day/week cutoffs must be LOCAL, not UTC.
        //
        // `toISOString().split('T')[0]` yields the UTC day, and `timestamp` is a
        // UTC ISO string, so the two agreed — but the USER'S day is local. On this
        // box (UTC+7) between local 00:00 and 07:00 the UTC date is still
        // yesterday, so "Longest Focus today" silently showed yesterday's best for
        // seven hours a day. (Same class of bug as every other toISOString().split
        // in this file — see MEMORY.md.)
        //
        // Fixed by comparing real epoch millis against a LOCAL midnight boundary
        // instead of comparing date strings, which also avoids lexicographic
        // string comparison of ISO timestamps entirely.
        const now = new Date();
        const startOfToday = new Date(now.getFullYear(), now.getMonth(), now.getDate()).getTime();
        const startOfWeekAgo = new Date(now.getFullYear(), now.getMonth(), now.getDate() - 7).getTime();

        const allLogs = db.prepare(`
            SELECT id, timestamp, app, title, duration_ms, category, is_browser_tracking, domain, url
            FROM logs WHERE duration_ms > 0
            ORDER BY timestamp ASC
        `).all() as any[];

        const logEpoch = (l: any) => {
            const t = new Date(l.timestamp).getTime();
            return Number.isFinite(t) ? t : 0;
        };
        const todayLogs = allLogs.filter((l: any) => logEpoch(l) >= startOfToday);
        const weekLogs = allLogs.filter((l: any) => logEpoch(l) >= startOfWeekAgo);

        const todayTop = findTopSessions(todayLogs);
        const weekTop = findTopSessions(weekLogs);
        const allTimeTop = findTopSessions(allLogs);

        const format = (s: any) => ({
            apps: s.apps,
            app: s.apps[0],
            category: s.category,
            title: s.title,
            durationSeconds: Math.round(s.durationMs / 1000),
            startTime: new Date(s.startTime).toISOString(),
            endTime: new Date(s.endTime).toISOString(),
        });

        return {
            today: todayTop.map(format),
            week: weekTop.map(format),
            allTime: allTimeTop.map(format),
        };
    } catch (err: any) {
        console.error('[DeskFlow] get-longest-focus error:', err);
        return { today: [], week: [], allTime: [] };
    }
});

// ── Dashboard Data Handlers ─────────────────────
electron_1.ipcMain.handle('get-dashboard-aggregates', async (_event, request: { period: string; dateOffset?: number; weekOffset?: number; platform?: string }) => {
  try {
    const { period = 'week', dateOffset = 0, platform } = request;
    const today = new Date();
    const start = new Date(today);
    if (period === 'week') { start.setDate(start.getDate() - 7 + (dateOffset || 0) * 7); }
    else if (period === 'month') { start.setMonth(start.getMonth() - 1 + (dateOffset || 0)); }
    else { start.setDate(start.getDate() - 1 + (dateOffset || 0)); }
    const end = new Date(today);
    if (platform) {
      end.setDate(end.getDate() + 1);
      const rows = db!.prepare('SELECT date, app_name, app_type, SUM(total_seconds) as total_seconds, SUM(session_count) as sessions FROM stats_daily WHERE date >= ? AND date < ? AND platform = ? GROUP BY date, app_name ORDER BY date').all(start.toISOString().slice(0, 10), end.toISOString().slice(0, 10), platform) as any[];
      return { success: true, period, dateRange: [start.toISOString().slice(0, 10), end.toISOString().slice(0, 10)], data: rows };
    }
    const rows = db!.prepare('SELECT date, app_name, app_type, SUM(total_seconds) as total_seconds, SUM(session_count) as sessions FROM stats_daily WHERE date >= ? AND date < ? GROUP BY date, app_name ORDER BY date').all(start.toISOString().slice(0, 10), end.toISOString().slice(0, 10)) as any[];
    const heatmap = new Map<string, any>();
    for (const r of rows) {
      const key = r.date + '|' + r.app_name;
      heatmap.set(key, { date: r.date, app_name: r.app_name, app_type: r.app_type, total_seconds: r.total_seconds, sessions: r.sessions });
    }
    return { success: true, period, dateRange: [start.toISOString().slice(0, 10), end.toISOString().slice(0, 10)], data: Array.from(heatmap.values()) };
  } catch (err: any) {
    console.error('[DeskFlow] get-dashboard-aggregates error:', err);
    return { success: false, error: err.message, data: [] };
  }
});

electron_1.ipcMain.handle('get-dashboard-data', async (_event, params: { period: string; dateOffset?: number }) => {
  try {
    const { period = 'today', dateOffset = 0 } = params;
    const today = new Date();
    let start: Date;
    if (period === 'today') { start = new Date(today); start.setHours(0, 0, 0, 0); }
    else if (period === 'week') { start = new Date(today); start.setDate(start.getDate() - 7 + dateOffset * 7); start.setHours(0, 0, 0, 0); }
    else { start = new Date(today); start.setHours(0, 0, 0, 0); }
    const end = new Date(today); end.setHours(23, 59, 59, 999);
    const dateStr = start.toISOString().slice(0, 10);
    const dailyTotal = db!.prepare('SELECT SUM(total_seconds) as total_seconds, SUM(session_count) as sessions FROM stats_daily WHERE date = ?').get(dateStr) as any;
    const topApps = db!.prepare('SELECT app_name, app_type, SUM(total_seconds) as total_seconds, SUM(session_count) as sessions FROM stats_daily WHERE date = ? GROUP BY app_name ORDER BY total_seconds DESC LIMIT 10').all(dateStr) as any[];
    const hourlyRows = period === 'week'
      ? db!.prepare('SELECT date, SUM(total_seconds) as total_seconds FROM stats_daily WHERE date >= ? AND date < ? GROUP BY date ORDER BY date').all(start.toISOString().slice(0, 10), new Date(end.getTime() + 86400000).toISOString().slice(0, 10)) as any[]
      : [];
    return { success: true, period, dateRange: [start.toISOString().slice(0, 10), end.toISOString().slice(0, 10)], dailyTotal: dailyTotal || { total_seconds: 0, sessions: 0 }, topApps, hourlyData: hourlyRows };
  } catch (err: any) {
    console.error('[DeskFlow] get-dashboard-data error:', err);
    return { success: false, error: err.message, dailyTotal: { total_seconds: 0, sessions: 0 }, topApps: [], hourlyData: [] };
  }
});

